(window.MATRIX_DATA_PARTS ||= Object.create(null))["data/poems-0001.js"] = [{"id":"poem-0631e89161a0aeb29547dad7","title":"铧锹儿","author":"萧德祥《小孙屠》","dynasty":"元","verses":["从来你行惯，曾途中历遍。","今日此行，须是意莫留连。","遣我朝夕恁忧煎，望得孩儿眼穿。","子母心，两处悬。","(和)鸿飞不到处，总被利名牵(末)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8584","tags":[]},{"id":"poem-0638a0518d5c8158c477bc34","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(末)告且听启：小官人镇日攻书，被东人急呼至，说着几句，百般打骂赶出去。","(贴)果恁的，奈我官人心性急，似撮盐入火内。","猜着就里，又敢是听人胡语？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1722","tags":[]},{"id":"poem-0645ea9f547acc397f585c2d","title":"阮郎归·歌停檀板舞停鸾","author":"黄庭坚","dynasty":"宋","verses":["歌停檀板舞停鸾。","高阳饮兴阑。","兽烟喷尽玉壶干。","香分小凤团。","雪浪浅，露花圆。","捧瓯春笋寒。","绛纱笼下跃金鞍。","归时人倚阑。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-751","tags":[]},{"id":"poem-0649c15614f13d32ec4eb7df","title":"赠兴善彻公上人","author":"李洞","dynasty":"唐","verses":["师资怀劒外，徒步管街东。","九里山横烧，三条木落风。","古池曾看鹤，新塔未吟虫。","夜久龙髯冷，年多麈尾空。","心宗本无碍，问学岂难同。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-825c52dd-8429-49ad-bfb8-c392320d4765","tags":[]},{"id":"poem-06510d0ea817fece4eb523a6","title":"摊破木兰花・木兰花·芳草裙腰一尺围","author":"贺铸","dynasty":"宋","verses":["芳草裙腰一尺围。","粉郎香润，清洒蔷薇。","为嫌风日下楼稀。","杨柳青阴，深闭朱扉。","枉是尊前调玉徽。","彩鸾何事逐鸡飞。","楚台赋客莫相违。","留住行云，好待郎归。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-67","tags":[]},{"id":"poem-065197c92d34615f57f9dacc","title":"搅群羊","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(旦)嫂嫂话难听，激得我心儿闷。","一马一鞍，再嫁傍人论。","夫去投军，谁敢为媒证？那有休书，谁敢来询问？你如何交奴交奴再嫁人？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8896","tags":[]},{"id":"poem-065ea6a803c485428eae1977","title":"雨","author":"杜甫","dynasty":"唐","verses":["山雨不作埿，江云薄为雾。","晴飞半岭鹤，风乱平沙树。","明灭洲景微，隐见岩姿露。","拘闷出门游，旷绝经目趣。","消中日伏枕，卧久尘及屦。","岂无平肩舆，莫辨望乡路。","兵戈浩未息，蛇虺反相顾。","悠悠边月破，郁郁流年度。","针灸阻朋曹，糠籺对童孺。","一命须屈色，新知渐成故。","穷荒益自卑，飘泊欲谁诉。","虺羸愁应接，俄顷恐违迕。","浮俗何万端，幽人有独步。","庞公竟独往，尚子终罕遇。","宿留洞庭秋，天寒潇湘素。","杖策可入舟，送此齿发暮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-cc5abbb6-01a9-4346-8ba9-29770f446154","tags":["洞庭湖"]},{"id":"poem-065f9785760f01dc967a154b","title":"浪淘沙·梦觉、透窗风一线","author":"柳永","dynasty":"宋","verses":["梦觉、透窗风一线，寒灯吹息。","那堪酒醒，又闻空阶，夜雨频滴。","嗟因循、久作天涯客。","负佳人、几许盟言，便忍把、从前欢会，陡顿翻成忧戚。","愁极。","再三追思，洞房深处，几度饮散歌阑，香暖鸳鸯被，岂暂时疏散，费伊心力。","云尤雨，有万般千种，相怜相惜。","恰到如今，天长漏永，无端自家疏隔。","知何时、却拥秦云态，愿低帏昵枕，轻轻细说与，江乡夜夜，数寒更思忆。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-145","tags":["宋词三百首"]},{"id":"poem-0663086da4c3beecc65ef35d","title":"三韵三篇 三","author":"杜甫","dynasty":"唐","verses":["烈士恶多门，小人自同调。","名利苟可取，杀身傍权要。","何当官曹清，尔辈堪一笑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-73368692-b14f-4e13-a388-ff5acccf9a12","tags":[]},{"id":"poem-0663a1bb00cb464171e9fbdc","title":"德升尚书再用前韵见示五绝 山寺寓居","author":"綦崇礼","dynasty":"宋","verses":["尘埃暗宫锦，耒耜安田庐。","陈力知不能，不止独何欤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-931b40cc-bd49-482e-b748-231df8650605","tags":[]},{"id":"poem-0668b5fe96025bad5f9efcb0","title":"酬张十八病中寄诗","author":"王建","dynasty":"唐","verses":["本性慵远行，绵绵病自生。","见君绸缪思，慰我寂寞情。","风幌夜不掩，秋灯照雨明。","彼愁此又忆，一夕两盈盈。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-684387fe-9020-4b93-97e8-37a7cda07cf3","tags":[]},{"id":"poem-066e6e7091aec5cdb6a4a81d","title":"九诵 岳神","author":"鲜于侁","dynasty":"宋","verses":["云蓊蔚兮山之巓，瞻岳灵兮望青天。","崭岩崷崪兮磅礴无垠，巄嵸嵂勃兮宁一以为仁。","草木杂而罗生兮人不可名，鸟兽蕃而走集兮虞不能知。","因高错事兮道此跻陛，登岱勒成兮胡为而七十二君。","齐余心兮不外，高余冠兮甚伟。","撷芳杜兮为衣，掇紫芝兮作佩。","柏实兮松华，石髓兮兰英。","蕙肴陈兮玉案，明水湛兮清尊。","诚拳拳兮不解，寐接神兮怳若有言。","嵩高峻极兮生甫与申，周道将明兮宣以中兴。","水旱不常兮虫螟以灾，稼穑卒荒兮民生流离。","劳来安集兮之子之功，祐此下民兮宁遗神羞。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-2f664807-005c-490c-b00d-f39014552a2e","tags":[]},{"id":"poem-0672a7199d76b93ed9b22f3a","title":"蝶恋花·美盼低迷情宛转","author":"周邦彦","dynasty":"宋","verses":["美盼低迷情宛转。","爱雨怜云，渐觉宽金钏。","桃李香苞秋不展。","深心黯黯谁能见。","宋玉墙高才一觇。","絮乱丝繁，苦隔春风面。","歌板未终风色便。","梦为蝴蝶留芳甸。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-511","tags":[]},{"id":"poem-0675e322edf132a43e47461f","title":"岩桂","author":"史绳祖","dynasty":"宋","verses":["四出花中异，三开格外芳。","名高评月品，韵胜霸秋香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-14c7abc7-0539-4a1e-bb28-4d38679d284d","tags":[]},{"id":"poem-0676ef4d4dba77506a57e606","title":"见薛大臂鹰作","author":"高适","dynasty":"唐","verses":["寒楚十二月，苍鹰八九毛。","寄言燕雀莫相啅，自有云霄万里高。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-17c901f7-75d0-48ce-ac16-95724c21dad9","tags":[]},{"id":"poem-067a63cc120393aa4e8f99f9","title":"嵩山十志十首 其四","author":"卢鸿一","dynasty":"唐","verses":["临泱漭兮背青荧，吐云烟兮合窅冥。","怳欻翕兮杳幽霭，意缥缈兮群仙会。","窅冥仙会兮枕烟庭，竦魂形兮凝视听。","闻夫至诚必感兮祈此巅，契颢气，养丹田，终彷像兮觏灵仙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-27a2907f-b550-4a46-8973-4e24d5e19dbf","tags":[]},{"id":"poem-067d9bb1c3c5d6aadf5fc692","title":"念奴娇·茂陵仙客","author":"李纲","dynasty":"宋","verses":["茂陵仙客，算真是、天与雄才宏略。","猎取天骄驰卫霍，如使鹰鹯驱雀。","鏖战皋兰，犁庭龙碛，饮至行勋爵。","中华疆盛，坐令夷狄衰弱。","追想当日巡行，勒兵十万骑，横临边朔。","亲总貔貅谈笑看，黠虏心惊胆落。","寄语单于，两君相见，何苦逃沙漠。","英风如在，卓然千古高著。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-543","tags":[]},{"id":"poem-067e4c1b1062045804373fc5","title":"途中逢友人","author":"李咸用","dynasty":"唐","verses":["大道将穷阮籍哀，红尘深翳步迟回。","皇天有意自寒暑，白日无情空往来。","霄汉何年征赋客，烟花随处作愁媒。","相逢且快眼前事，莫厌狂歌酒百杯。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-8d30f3cb-bc81-4c58-a337-ebf6a7a5a038","tags":[]},{"id":"poem-068675fb57c835a10eda4e7e","title":"经栖白旧院二首 一","author":"贯休","dynasty":"唐","verses":["竺卿何处去，触目尽凄凉。","不见中秋月，空余一炷香。","残花飘暮雨，枯叶盖啼螀。","谁礼新坟塔，萧条渭水傍。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-98da9e6a-be05-4f84-b49c-41ea3b29ba17","tags":[]},{"id":"poem-068a47f86cac18c1debf004b","title":"花影","author":"苏轼","dynasty":"宋","verses":["重重叠叠上瑶台，几度呼童扫不开。","刚被太阳收拾去，却教明月送将来。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-花影","tags":[]},{"id":"poem-0694d74c7aa6333fb013fdd9","title":"北苑侍宴杂咏诗 松","author":"徐铉","dynasty":"宋","verses":["细韵风中远，寒青雪后浓。","繁阴堪避雨，效用待东封。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-2c24b0c9-4ca8-4cc1-98b4-08e59f977e62","tags":[]},{"id":"poem-06a521509eb0277678441d1f","title":"赠率子连  其三","author":"王祜","dynasty":"宋","verses":["心意逍遥物莫知，山中山下识人稀。","想君绝虑离尘土，不是王乔即令威。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-2276958a-24e4-4fad-a48f-bace26af5bfc","tags":[]},{"id":"poem-06af73ffa437c687fa8dafa2","title":"金山","author":"皇甫冉","dynasty":"唐","verses":["中江一柱碧崚嶒，壁立千寻我独登。","梵呗波随招过客，钟声船载送归僧。","窗前白上浪三尺，岭上青堆云几层。","六代风流衰歇尽，慿栏感喟意难胜。","（见丹徒陶绍莱辑《润州唐人集》卷七，云：「见净谈《金山志》及缪潜《新志》。","」）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-239006e5-0f8f-4e06-94fc-3454403affff","tags":[]},{"id":"poem-06b4f9916fb86b8978bb7b81","title":"紫极宫","author":"王镃","dynasty":"宋","verses":["拜章台上月如霜，云湿阑干面面凉。","道士醮归秋夜浄，满身薰得紫藤香。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-6595877f-2437-4541-82a9-9f37c45bb4ed","tags":[]},{"id":"poem-06b88c4f22d4ac9f03152d27","title":"咏李","author":"张𬸦","dynasty":"唐","verses":["李树子，元来不是偏。","巧知娘子意，掷果到渠边。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-3023a38a-6841-4909-95e2-5f261c1f02e9","tags":[]},{"id":"poem-06b89b52dad08acee76a339b","title":"贺新郎·篆缕销香鼎","author":"潘汾","dynasty":"宋","verses":["篆缕销香鼎。","翠沈沈、庭阴转午，画堂人静。","芳草王孙知何处，惟有杨花糁径。","正玉枕、瞢腾初醒。","门外残红春已去，镇无聊、酒厌厌病。","云髻，未整。","江南旧事休重省。","但天涯、寻消问息，断鸿难倩。","月满西楼凭阑久，依旧归期未定。","便只恐、瓶沈金井。","嘶骑不来银烛暗，枉教人、立尽梧桐影。","谁伴我，对鸾镜。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-109","tags":["宋词三百首"]},{"id":"poem-06d1aad9933463cb06eba9d4","title":"听筝","author":"李端","dynasty":"唐","verses":["鸣筝金粟柱，素手玉房前。","欲得周郎顾，时时误拂弦。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-7f3799de-78b4-49bc-b6d8-a5fa3ecacd33","tags":["唐诗三百首","五言绝句","音乐"]},{"id":"poem-06d55d9e96c6ce844857afdb","title":"汉宫词","author":"崔道融","dynasty":"唐","verses":["独诏胡衣出，天花落殿堂。","他人不敢妬，垂泪向君王。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-2a815db8-4abd-4219-aeeb-02be5d657b19","tags":[]},{"id":"poem-06d933420a9a02a8d71c95ac","title":"兵要望江南 医方第二十九（十六首） 十六","author":"易静","dynasty":"唐","verses":["山瘴气，岚谷用恒山。","独头大蒜乌梅肉，速将酒煮便能痊，谨记此良言。","（恒山二两，独头蒜一两，乌梅二十枚，咬咀，用酒二盏，煎至一大盏，分为二服。","初一服未发时吃，次一服已发时吃。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-18ec9908-c73b-4201-9a70-f20d32701ef6","tags":[]},{"id":"poem-06dfd925651063fa7b737882","title":"侍郎宅泛池","author":"徐凝","dynasty":"唐","verses":["莲子花边回竹岸，鸡头叶上荡兰舟。","谁知洛北朱门里，便到江南绿水游。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-d3e952ab-2299-4e42-a5a8-2f82a8fca5ef","tags":[]},{"id":"poem-06e188690275319af61be413","title":"御街行·凌寒架雪知春近","author":"曹勋","dynasty":"宋","verses":["凌寒架雪知春近。","闲探处、如相问。","溪流清浅暮云低，玉蓓横斜风定。","晚枝雀啅，幽姿方展，还映疏篁冷。","镜鸾妆罢明梢嫩。","犹记宜相并。","如今却月别传香，知引何人幽兴。","不堪楼上，昭华吹断，声与愁肠尽。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-184","tags":[]},{"id":"poem-06edead5d88230e027c15231","title":"送成都漕","author":"刘跂","dynasty":"宋","verses":["里巷居偏近，生平月亦同。","开怀一笑语，转首两西东。","共是尘劳内，全输吏隠中。","鱼来勤尺素，淮汴古来通。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-6d6975e3-0fc9-4136-b16f-516d062a8331","tags":[]},{"id":"poem-06f45ba1bae2698c9fbaa68a","title":"寄王侍御","author":"张籍","dynasty":"唐","verses":["爱君紫阁峰前好，新作书堂药灶成。","见欲移居相近住，有田多与种黄精。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-afb264e3-d77f-4320-8a74-99504f66893a","tags":[]},{"id":"poem-06fa9f0108ac353c585d3385","title":"小重山·春入神京万木芳","author":"和凝","dynasty":"五代","verses":["春入神京万木芳，禁林莺语滑，蝶飞狂。","晓花擎露妨啼妆，红日水，风和百花香。","烟锁柳丝长，御沟澄碧水，转池塘。","时时微雨洗劫风光，天衢远，到处引笙簧。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-13","tags":[]},{"id":"poem-07143397bc086d6aa69ac413","title":"龙眠居士画十六大阿罗汉赞  其四","author":"李纲","dynasty":"宋","verses":["华林扰虎，手举数珠。","驯彼鬰屈，亦用兹乎。","巨颡修鳞，能怖童子。","慈眼视之，毒心自弭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-1bfa6e45-aeea-4e83-9a7d-d636cacb0f96","tags":[]},{"id":"poem-0717a0e118f9f947fab5b11c","title":"相和歌辞 蜀道难","author":"李白","dynasty":"唐","verses":["噫吁嚱！危乎高哉！蜀道之难难于上青天！蚕丛及鱼凫，开国何茫然。","尔来四万八千岁，乃与秦塞通人烟。","西当太白有鸟道，可以横绝峨眉巅。","地崩山摧壮士死，然后天梯石栈方钩连。","上有六龙回日之高标，下有冲波逆折之回川。","黄鹤之飞尚不得，猨猱欲度愁攀缘。","青泥何盘盘，百步九折萦岩峦。","扪参历井仰胁息，以手抚膺坐长叹。","问君西游何时还？畏途巉岩不可攀。","但见悲鸟号枯木，雄飞呼雌绕林间。","又闻子规啼夜月，愁空山，蜀道之难难于上青天！使人听此雕朱颜。","连峰去天不盈尺，枯松倒挂倚绝壁。","飞湍瀑流相喧豗，砅崖转石万壑雷。","其崄也若此，嗟尔远道之人胡为乎来哉？劒阁峥嵘而崔嵬，一夫当关，万夫莫开。","所守或匪亲，化为狼与豺。","朝避猛虎，夕避长蛇。","磨牙吮血，杀人如麻。","锦城虽云乐，不如早还家。","蜀道之难难于上青天，侧身西望长咨嗟。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-e117d224-39ca-4eba-a047-0d36ce8b8c26","tags":["唐诗三百首","山水","抒情","乐府","相和歌辞"]},{"id":"poem-071ac6cde1cbd7f8526c7e5e","title":"赠宾贡","author":"裴说","dynasty":"唐","verses":["惟君怀至业，万里信悠悠。","路向东[溟]出，枝来北阙求。","家无一夜梦，帆挂隔年秋。","鬓发争禁得，孤舟往复愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-1084793e-4e3a-41b7-9808-259e0be11113","tags":[]},{"id":"poem-071bb0906a4e40d3cf603a27","title":"除书学博士呈时宰","author":"米芾","dynasty":"宋","verses":["半生湖海看青山，惯佩笭箵揽辔艰。","晓起初驰朱雀路，霜华惭缀紫宸班。","百寮卑处瞻丹陛，五色光中望玉颜。","浪说书名落人世，非公那解彻天关。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-9227b30d-d1c3-4820-9625-63caa8066ca7","tags":[]},{"id":"poem-07351fbea458973e202628a5","title":"山中怀刘修","author":"鲍溶","dynasty":"唐","verses":["松老秋意孤，夜凉吟风水。","山人在远道，相忆中夜起。","春光如不至，幽兰含香死。","响象离鹤情，念来一相似。","月斜掩扉卧，又在梦魂里。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ecf449e2-0bb7-44b4-ad5e-42b6dd058af8","tags":[]},{"id":"poem-0739304e864cb16bc6ec71bc","title":"天下乐","author":"杨景贤","dynasty":"元","verses":["稳情取和气春风满画堂，宰下肥羊，安排的五味香，与俺那菜馒头的老兄腾了肚肠。","陪妆奁留他做丈夫，舍身躯与他做正房，可知道男儿当自强。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2329","tags":[]},{"id":"poem-0740bc68afc617373ff21a1d","title":"晚秋 四","author":"佚名","dynasty":"唐","verses":["髪为多愁白，心缘久客悲。","更遭缧绁事，因此改容仪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-6f3fd8ef-1897-4446-9fa0-cd5134bfc792","tags":[]},{"id":"poem-0747140d26a41ec510cb4719","title":"偶然五首 四","author":"皎然","dynasty":"唐","verses":["虏语嫌不学，胡音从不翻。","说禅颠倒是，乐杀金王孙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-f29f9b32-c701-48c3-8e06-9407d2cc25f5","tags":[]},{"id":"poem-0749ba1f20263931a5676040","title":"凤凰台","author":"杜甫","dynasty":"唐","verses":["亭亭凤凰台，北对西康州。","西伯今寂寞，凰声亦悠悠。","山峻路绝踪，石林气高浮。","安得万丈梯，为君上上头。","恐有无母雏，饥寒日啾啾。","我能剖心出，饮啄慰孤愁。","心以当竹实，炯然无外求。","血以当醴泉，岂徒比清流。","所贵王者瑞，敢辞微命休。","坐看彩翮长，举意八极周。","自天衔瑞图，飞下十二楼。","图以奉至尊，凤以垂鸿猷。","再光中兴业，一洗苍生忧。","深衷正为此，群盗何淹留。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-3cf03c99-a183-42d3-b280-0f955523ad22","tags":[]},{"id":"poem-074e81a64b240a0aec47f830","title":"早蝉","author":"李咸用","dynasty":"唐","verses":["门柳不连野，乍闻为早蝉。","游人无定处，入耳更应先。","暂默斜阳雨，重吟远岸烟。","前年湘竹里，风激遶离筵。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-978164b2-cc71-4ee7-b99e-250dbee9f7f5","tags":[]},{"id":"poem-074ff1360f7317c8e4d641e9","title":"毗陵三题  其一","author":"释居简","dynasty":"宋","verses":["闯簷起渊潜，涛怒欲翻壁。","两雄竞厥壮，跼领勇舒脊。","令人未见神先悸，如见当年李生醉。","醉乡汗漫渺无津，墨蜚素壁风蜚腥。","骧云掀雾妙入神，不特神妙尤夺真。","乡来识真人已朽，所见不知如此否。","或谓此儿鳞介胄，幻作人间写生手。","坐令五月六月间，商羊起舞旱魃走。","客窗夜老闻天籁，逸响琅然风雨晦。","晓入西游柱史家，因知壁有蜿蜒沕。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-3f2abff7-f878-44e9-b499-d04e144342bb","tags":[]},{"id":"poem-0751612e6f20d22d44cd5642","title":"椒聊","author":"佚名","dynasty":"先秦","verses":["椒聊之实，蕃衍盈升。彼其之子，硕大无朋。椒聊且，远条且。","椒聊之实，蕃衍盈匊。彼其之子，硕大且笃。椒聊且，远条且。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-116","tags":[]},{"id":"poem-0755f07e31611ab82687fea1","title":"同前","author":"无名氏《张协状元》","dynasty":"元","verses":["眉儿和那眼儿，与我儿无二，身材袅娜腰肢细。","(外)我瞥见你门，心下便怜伊。","因甚脸憔翠？(后)不知怎底？怎底？鲜血污衣。","(合)缘何如是？(旦)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2701","tags":[]},{"id":"poem-075eb3425affa9a9707e6381","title":"浣溪沙·珠箔随檐一桁垂","author":"王采","dynasty":"宋","verses":["珠箔随檐一桁垂。","绣屏遮枕四边移。","春归人懒日迟迟。","旧事只将云入梦，新欢重借月为期。","晚来花动隔墙枝。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-932","tags":[]},{"id":"poem-0766a0a50a09a30fdc68ffcc","title":"有约","author":"司马光","dynasty":"宋","verses":["黄梅时节家家雨，青草池塘处处蛙。","有约不来过夜半，闲敲棋子落灯花。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-有約","tags":[]},{"id":"poem-076f0ee7cff05ef4fe018716","title":"清平乐·芗林春色","author":"向子𬤇","dynasty":"宋","verses":["芗林春色。","杯面云腴白。","醉里不知天地窄。","真是人间欢伯。","风流玉友争妍。","酪奴可与忘年。","空诵少陵佳句，饮中谁与俱仙。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-146","tags":[]},{"id":"poem-0777d1930551404d554ec7d1","title":"花港观鱼","author":"王镃","dynasty":"宋","verses":["桃花落尽杏花嫣，碧港红沉水底天。","山雨忽晴风亦退，钓鱼人在小湖船。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-80fed261-dab1-44a0-9b5d-60b28404680b","tags":[]},{"id":"poem-0778703d08e59b97a664b786","title":"芰荷香·醉凝眸","author":"仲并","dynasty":"宋","verses":["醉凝眸。","正行云遮断，澄练江头。","皓月今宵何处，不管中秋。","朱阑倚遍，又微雨、催下危楼。","秋风空响更筹。","不将好梦，吹过南州。","浮远轩窗异日到，山空云净，江远天浮。","别去客怀，无赖准拟开愁。","冰轮好在，解随我、天际归舟。","何须舞袂歌喉。","一觞一咏，谈笑风流。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-201","tags":[]},{"id":"poem-0789a60a9422e4082c84d036","title":"唐享昊天乐 第二","author":"则天皇后","dynasty":"唐","verses":["瞻紫极，望玄穹。","翘至恳，罄深衷。","听虽远，诚必通。","垂厚泽，降云宫。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-d3715888-a6cc-4332-b3fe-d8fa4a2f27be","tags":[]},{"id":"poem-07a0eb29cc2a5f34ec9c6283","title":"越裳贡白雉","author":"丁仙芝","dynasty":"唐","verses":["圣哲承休运，伊夔列上台。","覃恩丹徼远，入贡素翚来。","北阙欣初见，南枝顾未回。","歛容残雪净，矫翼片云开。","驯扰将无惧，翻飞幸不猜。","甘从上林里，饮啄自徘徊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-a04e286d-365c-465f-be1e-6bd6497c38f9","tags":[]},{"id":"poem-07a2d55716a5481770cce65a","title":"定风波·问讯山东窦长卿","author":"王质","dynasty":"宋","verses":["问讯山东窦长卿。","苍苍云外且垂纶。","流水落花都莫问，等取，榆林沙月静边尘。","江面不如杯面阔，卷起，五湖烟浪入清尊。","醉倒投床君且睡，却怕，挑灯看剑忽伤神。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-338","tags":[]},{"id":"poem-07a5f5896cdde6de6165d906","title":"过三闾庙","author":"戴叔伦","dynasty":"唐","verses":["沅湘流不尽，屈子怨何深！","日暮秋风起，萧萧枫树林。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-過三閭廟","tags":[]},{"id":"poem-07b9e0f3c3ec4dc8aa9bc354","title":"多丽·人间世","author":"高登","dynasty":"宋","verses":["人间世，偶然攘臂来游。","何须恁、乾坤角抵，又成冷笑俳优。","且宽心、待他天命，谩鼓舌、夸吾人谋。","李广不侯，刘蕡未第，千年公论合谁羞。","往矣瓦飘无意，甑堕懒回头。","真堪笑，直钩论议，圆枘机筹。","幸斯道、元无得丧，壮心岂有沈浮。","好温存、困中节概，莫冷落、穷里风流。","酒滴珍珠，饭钞云子，醉饱卧信缘休。","归去也，幅巾谈笑，卒岁且优游。","循环事，亡羊须在，失马何忧。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-229","tags":[]},{"id":"poem-07bbbb9ac2dfefe6377ae96f","title":"辋川闲居赠裴秀才迪","author":"王维","dynasty":"唐","verses":["寒山转苍翠，秋水日潺湲。","倚杖柴门外，临风听暮蝉。","渡头余落日，墟里上孤烟。","复值接舆醉，狂歌五柳前。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-a2b4e8ca-92e3-4101-8a54-739b8f1d8184","tags":["唐诗三百首","写景","抒情","秋天","五言律诗"]},{"id":"poem-07bf5c8db623cf0f3f8c36a3","title":"绝句","author":"权审","dynasty":"唐","verses":["得即高歌失即休，多悲多恨谩悠悠。","今朝有酒今朝醉，明日愁来明日愁。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-43199678-079e-4d21-8f2f-811c906c1d34","tags":[]},{"id":"poem-07c781b65a82d6640870d981","title":"山出云","author":"陆畅","dynasty":"唐","verses":["灵山蓄云彩，纷郁出清晨。","望树繁花白，看峰小雪新。","映松张盖影，依涧布鱼鳞。","高似从龙处，低如触石频。","浓光藏半岫，浅色类飘尘。","玉叶开天际，遥怜占早春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-71b52a42-55e2-4a93-87ab-c86f12b2b55f","tags":[]},{"id":"poem-07cf9e44f42155651f013fa2","title":"邵尧夫先生哀辞二首  其二","author":"司马光","dynasty":"宋","verses":["慕德闻风久，论交倾盖新。","何须半面旧，不待一言亲。","讲道切磋直，忘怀笑语真。","重言蒙跖实，佩服敢书绅。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-ad763840-3d39-48de-ba13-89cf95fcd8d1","tags":[]},{"id":"poem-07d503af","title":"晚登三山还望京邑","author":"谢朓","dynasty":"南朝齐","verses":["灞涘望长安，河阳视京县。","白日丽飞甍，参差皆可见。","余霞散成绮，澄江静如练。","喧鸟覆春洲，杂英满芳甸。","去矣方滞淫，怀哉罢欢宴。","佳期怅何许，泪下如流霰。","有情知望乡，谁能鬒不变。"],"enabled":true,"collection":"历代名篇","source":"《文选》卷二十七谢朓《晚登三山还望京邑》。","tags":["山水","思乡"]},{"id":"poem-07d9c5bc7773a4df19701adf","title":"寄西山胡汾吴樵","author":"贯休","dynasty":"唐","verses":["带经锄陇者，何止手胼胝。","觅句句句好，慙予筋力衰。","云塠临案冷，鹿队过门迟。","相忆空回首，江头日暮时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-17d6e480-90d2-4c24-a800-0192028a812e","tags":[]},{"id":"poem-07e2b4c654e61aa03aeb09ac","title":"天育骠骑歌","author":"杜甫","dynasty":"唐","verses":["吾闻天子之马走千里，今之画图无乃是。","是何意态雄且杰，骏尾萧梢朔风起。","毛为绿缥两耳黄，眼有紫燄双瞳方。","矫矫龙性合变化，卓立天骨森开张。","伊昔太仆张景顺，监牧攻驹阅清峻。","遂令大奴守天育，别养骥子怜神俊。","当时四十万匹马，张公叹其材尽下。","故独写真传世人，见之座右久更新。","年多物化空形影，呜呼健步无由骋。","如今岂无騕褭与骅骝，时无王良伯乐死即休。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c28c271b-70b9-422c-8bfd-6a062f40d40c","tags":[]},{"id":"poem-07e3271be2bea01bfae4e2e3","title":"立春后一日风雨殊有寒色偶成","author":"李纲","dynasty":"宋","verses":["竟夕北风号，春回雨已膏。","归程离海峤，旧服理绨袍。","宿瘴须寒压，清愁欲醉逃。","何当入江浙，雪片洒鹅毛。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-a4339826-2b2b-44fd-abb9-dcdb2c28b698","tags":[]},{"id":"poem-0801d4a195f2cdae81dfe6ce","title":"引驾行·梅梢琼绽","author":"晁补之","dynasty":"宋","verses":["梅梢琼绽，东君次第开桃李。","痛年年、好风景，无事对花垂泪。","园里。","旧赏处、幽葩柔条，一一动芳意。","恨心事。","春来间阻，忆年时、把罗袂。","雅戏。","樱桃红颗，为插边明丽。","又渐是。","樱桃尝新，忍把旧游重记。","何意。","便云收雨歇，瓶沈簪折两无计。","谩追悔。","凭谁向说，只厌厌地。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-147","tags":[]},{"id":"poem-081c8dccf6bb2bd2217629d3","title":"龟虽寿","author":"曹操","dynasty":"汉","verses":["神龟虽寿，犹有竟时。","腾蛇乘雾，终为土灰。(腾一作：螣)。","老骥伏枥，志在千里。","烈士暮年，壮心不已。","盈缩之期，不但在天；养怡之福，可得永年。","幸甚至哉，歌以咏志。"],"enabled":true,"collection":"曹操诗集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/曹操诗集/caocao.json#record-5","tags":[]},{"id":"poem-081d2965b63f9dcc519b4678","title":"句  其三","author":"孟宾于","dynasty":"宋","verses":["水国两亲应探榜，龙门三月又伤春。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-3a22d900-736a-463f-b98f-743cb2ec6169","tags":[]},{"id":"poem-082440c72242ecdbf1228903","title":"浣溪沙·松菊秋来好在无","author":"毛滂","dynasty":"宋","verses":["松菊秋来好在无。","寄声猿鹤莫情疏。","渊明不老久踟蹰。","打鼓枫林谁作社，枕溪茅屋忆吾庐。","去年醉倒倩人扶。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-737","tags":[]},{"id":"poem-084280f816f61e28c712f470","title":"三犯后庭花","author":"杨景贤","dynasty":"元","verses":["将抬着花轿篮，妆里着酒食扭。","就小亭开宴破橙柑，玉山摧不用搀。","相期相约两相耽，是和非一任谈，尽傍人将冷句搀。","对上了菱花、菱花鸾鉴，非是我故贪淫滥，夫妇之情仔细参。","见你富时节承览，贫时节虚赚，不得和咸。","君居地北我天南，我怎肯将郎君陷？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4502","tags":[]},{"id":"poem-08440f86015cb69a04c7830f","title":"山坡羊","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["撇得我不尴不尬，闪得我无聊无赖。","亲家，你一霎时认真逼他去投江海，怎布摆，祸从天上来。","你嫡亲父母尚且不遮盖，反将他谐老夫妻生打开。","(合)哀哉！扑簌簌泪满腮。","伤怀，生擦擦痛怎挨！(外、净上)隔墙须有耳，窗外岂无人。","亲家为何啼哭？(老旦)亲家，不好了，我的媳妇投江死了。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8228","tags":[]},{"id":"poem-084f4668e76be6e98ef1db0b","title":"僻居酬友人","author":"伍乔","dynasty":"宋","verses":["僻居惟爱近林泉，幽径闲园任藓连。","向竹掩扉随鹤息，就溪安石学僧禅。","古琴带月音声正，山果经霜气味全。","多谢故交怜朴野，隔云时复寄佳篇。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-dee006eb-e2ce-450a-86a8-247490fa67a4","tags":[]},{"id":"poem-08510d329943573aea06d374","title":"闲居拟齐梁四首 一","author":"贯休","dynasty":"唐","verses":["夜雨山草滋，爽籁生古木。","闲吟竹仙偈，清于嚼金玉。","蟋蟀啼坏墙，苟免悲局促。","道人优昙花，迢迢远山绿。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-2087809f-1af6-44d9-8b56-697c355752c1","tags":[]},{"id":"poem-085166b6921e04e5bc314e6c","title":"洋州三十景 过溪亭","author":"鲜于侁","dynasty":"宋","verses":["溪桥入庭下，杖履可忘忧。","谁识钓璜翁，有时抛直钩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-8b1541cb-66bc-4a18-ac1b-957aa444a060","tags":[]},{"id":"poem-0855332d967f3661ef1d557c","title":"郊庙歌辞 梁太庙乐舞辞 撤豆","author":"不详","dynasty":"唐","verses":["笙镛洋洋，庭燎煌煌。","明星有烂，祝史下堂。","[笾]豆斯撤，礼容有章。","克勤克俭，无怠无荒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-bee147ae-b09f-4b5b-a916-8297f1584642","tags":[]},{"id":"poem-085a244338a0633419833007","title":"郊庙歌辞 祀九宫贵神乐章 凯安","author":"不详","dynasty":"唐","verses":["盛德陈万舞，威棱畅九垓。","风云交律候，日月丽昭回。","行庆休祥发，乘和春气来。","百神肃临享，荡荡天门开。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-e02abcc5-bc03-4306-b0ab-f5f049104c9c","tags":[]},{"id":"poem-085e201b443af3d8694251d8","title":"感恩多·自从南浦别","author":"牛峤","dynasty":"五代","verses":["自从南浦别，愁见丁香结。","近来情转深，忆鸳衾。","几度将书托烟雁，泪盈襟。","泪盈襟，礼月求天，愿君知我心。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-7","tags":[]},{"id":"poem-086344a12aee38574255501c","title":"经栖白旧院二首 二","author":"贯休","dynasty":"唐","verses":["国宝还亡一，时多李德林。","故人卿相泣，承制渥恩深。","旧藳谁收得，空堂影似吟。","裴回不能去，寒日下西岑。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-3ae51901-884c-41b3-afab-24d227da488d","tags":[]},{"id":"poem-0867f5c7793e277af2873d9f","title":"寄严文炳  其五","author":"陈造","dynasty":"宋","verses":["严子老於菟，彪炳踞贤关。","可怜五车学，仅博九品官。","客程望至喜，江阔山丛攒。","缅怀造物心，念子讵能安。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-11fee861-9aff-40fb-b786-e820776f22db","tags":[]},{"id":"poem-0868c94f3d7719d129654412","title":"病中二首","author":"方左钺","dynasty":"宋","verses":["日费行将典到琴，穷愁那复病相侵。","倩人合药无真料，就枕吟诗苦见心。","仆献奇方单用草，医言速效莫如参。","池亭咫尺无由到，空听蝉声想绿深。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-c9d90a0b-6ab8-4fc1-8327-2c3de0d669c7","tags":[]},{"id":"poem-0869e1a3cdfe3c190e0d14b3","title":"田家","author":"范成大","dynasty":"宋","verses":["昼出耘田夜绩麻，村庄儿女各当家。","童孙未解供耕织，也傍桑阴学种瓜。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-田家","tags":[]},{"id":"poem-086fc638960a2ca42f955aa2","title":"生查子·关山魂梦长","author":"王观","dynasty":"宋","verses":["关山魂梦长，塞雁音书少。","两鬓可怜青，一夜相思老。","归傍碧纱窗，说与人人道。","真个别离难，不似相逢好。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-36","tags":["宋词三百首"]},{"id":"poem-0877f0d9bbfa46c5616fafd7","title":"菩萨蛮 其十一","author":"温庭筠","dynasty":"唐","verses":["南园满地堆轻絮，愁闻一霎清明雨。","雨后却斜阳，杏花零落香。","无言匀睡脸，枕上屏山掩。","时节欲黄昏，无聊独倚门。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-1-juan.json#record-10","tags":[]},{"id":"poem-087c7e98cbd8e945f06c319a","title":"临江仙·披袍窣地红宫锦","author":"和凝","dynasty":"五代","verses":["披袍窣地红宫锦，莺语时啭轻音。","碧罗冠子稳犀簪，凤凰双飐步摇金。","肌骨细匀红玉软，脸波微送春心。","娇羞不肯入鸳衾，兰膏光里两情深。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-6-juan.json#record-16","tags":[]},{"id":"poem-0883e3851f95fad8d9a8fe4b","title":"永明山居诗（六十九首） 三十一","author":"延寿","dynasty":"唐","verses":["有山有水更何忧，知足能令万事休。","大道不从心外得，浮荣须向世间求。","冲开烟缕飞黄鸟，点破潭心漾白鸥。","好景尽归余掌握，岂劳艰险访瀛洲。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-5bcddb2a-b3f1-48de-bf40-1bfa66ef3064","tags":[]},{"id":"poem-088a1210b30b44d6ee330829","title":"虞美人·风回小院庭芜绿","author":"李煜","dynasty":"五代","verses":["风回小院庭芜绿，柳眼春相续。","凭栏半日独无言，依旧竹声新月似当年。","笙歌未散尊前在，池面冰初解。","烛明香暗画楼深，满鬓清霜残雪思难禁。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-27","tags":[]},{"id":"poem-088ab2366ee874aa95bf5a17","title":"和渊眀拟古九首  其八","author":"李纲","dynasty":"宋","verses":["结髪慕古人，绝俗期远游。","如登太山顶，志气小九州。","古今会迁变，万壑无停流。","向来富贵者，累累但荒丘。","汉唐已磨灭，况复秦与周。","惟余节义士，可向编简求。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-44680883-c6af-4277-be33-0ca98d845481","tags":[]},{"id":"poem-089205f32f9aa6122c0a8c31","title":"和王彦舟","author":"米芾","dynasty":"宋","verses":["混尘慵走俗，陟𪩘喜非期。","漠漠江雨歇，溶深春水时。","陶潜那寄傲，惠远更能诗。","吏自成稀阔，言归心尚迟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-a4beefc4-dd95-483c-84f1-f35f40dc922f","tags":[]},{"id":"poem-089f9680bdaff4e031a0eaad","title":"前腔","author":"柯丹邱《荆钗记》","dynasty":"元","verses":["(生)再听因依，说起教人珠泪垂。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8345","tags":[]},{"id":"poem-08a5a63c59e9c574febf5989","title":"拟寒山 十","author":"泰钦","dynasty":"唐","verses":["飒飒西风起，飘飘细雨飞。","前村孤岭上，樵父拥蓑归。","蹑履寻荒径，搘筇似力微。","时人应笑我，笑我者还稀。","（《卍续藏经》本宋释子升、如祐编《禅门诸祖师偈颂》卷上之上。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-8260b7d7-ddb1-47b2-8460-a04767cf26f5","tags":[]},{"id":"poem-08ae1a2ba9b75e11a12cc719","title":"越州怀古","author":"张祜","dynasty":"唐","verses":["振檝大江东，前林波万顷。","高秋海天阔，色落湖山影。","行寻王谢迹，望望登绝岭。","荒林草木瘦，古树泉石冷。","昔游不可见，牢落余风景。","穷愁心未死，一笔聊复秉。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-7c477b22-0ef3-48ee-86d4-b9403d805cb6","tags":[]},{"id":"poem-08b29e31aadc6907f8998083","title":"救生寺望春寄畅当","author":"李端","dynasty":"唐","verses":["东西南北望，望远悲潜蓄。","红黄绿紫花，花开看不足。","今年与子少相随，他年与子老相逐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-e321d83c-6578-4f48-a774-aa4abc5d4f9d","tags":[]},{"id":"poem-08c1edfa92dddf037018b808","title":"浣溪沙·一向年光有限身","author":"晏殊","dynasty":"宋","verses":["一向年光有限身。","等闲离别易消魂。","酒筵歌席莫辞频。","满目山河空念远，落花风雨更伤春。","不如怜取眼前人。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-160","tags":["宋词三百首"]},{"id":"poem-08c528d61c70b613154a916f","title":"帝京篇十首 四","author":"太宗皇帝","dynasty":"唐","verses":["鸣笳临乐馆，眺听欢芳节。","急管韵朱弦，清歌凝白雪。","彩凤肃来仪，玄鹤纷成列。","去兹郑卫声，雅音方可悦。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-fa374b2b-c196-4362-b4ad-8931fc9a8860","tags":[]},{"id":"poem-08c65d6f71282ef63cc6459b","title":"建元寺集皇甫侍御书阁","author":"皎然","dynasty":"唐","verses":["不因居佛里，无事得相逢。","名重朝端望，身高俗外踪。","机闲看净水，境寂听疎钟。","宣室恩长在，知君志未从。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-6cf38d83-ee7f-4f5d-b670-c2115430cb34","tags":[]},{"id":"poem-08d04d4a1bf566e1395f8c57","title":"崇宁元年五月十六日天汉桥月下闲步","author":"华镇","dynasty":"宋","verses":["闲来步月上银潢，天宇无尘夜色凉。","双阙高寻佳气耸，三街平衬绿槐长。","沈沈琳馆东西迥，褭褭珠楼左右光。","归去不须寻蜀客，莫教知到斗牛傍。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-1efd67a1-2c7f-447c-a750-a02367f1f920","tags":[]},{"id":"poem-08d1deb351a8796658f6e772","title":"偈颂（幷序○序为南岳齐己撰） 十","author":"居遁","dynasty":"唐","verses":["自小从师学祖宗，闲华犹似缠人蜂。","僧真不假栖（《景德传灯录》卷二九作「居」）云外，得后无心色亦空（《景德传灯录》作「知无色自空」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-460f77ab-9c64-4f82-93db-b2ef7414f9fd","tags":["衡山"]},{"id":"poem-08d21d5b2a8da7dff04805b6","title":"念奴娇·光风转蕙","author":"郭世模","dynasty":"宋","verses":["光风转蕙，泛崇兰、漠漠满城飞絮。","金谷楼危山共远，几点亭亭烟树。","枝上残花，胭脂满地，乱落如红雨。","青春将暮，玉箫声在何处。","无端天与娉婷，帘钩鹦鹉，梦断闻残语。","玉骨瘦来无一把，手挹罗衣看取。","江北江南，灵均去后，谁采苹花与。","香销云散，断魂分付潮去。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-395","tags":[]},{"id":"poem-08d87c1d3370454aa2bcdb72","title":"万丈潭","author":"杜甫","dynasty":"唐","verses":["青溪合冥莫，神物有显晦。","龙依积水蟠，窟压万丈内。","跼步凌垠堮，侧身下烟霭。","前临洪涛宽，却立苍石大。","山色一径尽，崖绝两壁对。","削成根虚无，倒影垂澹瀩。","黑如湾澴底，清见光炯碎。","孤云倒来深，飞鸟不在外。","高萝成帷幄，寒木累旌旆。","远川曲通流，嵌窦潜泄濑。","造幽无人境，发兴自我辈。","告归遗恨多，将老斯游最。","闭藏修鳞蛰，出入巨石碍。","何事暑天过，快意风雨㑹。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b1b841ee-a837-427e-aecc-1da457c3b102","tags":[]},{"id":"poem-08f147be066923f7aaaaf01d","title":"次韵傅教授景仁马绿荔支","author":"王十朋","dynasty":"宋","verses":["玉座奇包未与颁，伏波家果忽堆盘。","宜书蔡谱均称绿，不比韩诗止咏丹。","荐李徒夸碧实脆，嚼瓜未觉水晶寒。","羡君衫鬓巧相似，我坐郡厅惭素餐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-bbddd824-4c90-46ae-8b7a-58bd9e23c580","tags":[]},{"id":"poem-08f3f3d878a8dcbcecae08d8","title":"奉和圣制送张说巡边","author":"卢从愿","dynasty":"唐","verses":["上将发文昌，中军静朔方。","占星引旌节，择日拜坛场。","礼乐临轩送，威声出塞扬。","安边俟帷幄，制胜在岩廊。","作鼓将军气，投醪壮士觞。","戒途遵六月，离赠动三光。","槐路清梅暑，蘅臯起麦凉。","时文仰雄伯，耀武震遐荒。","衽席知无战，兵戈示不忘。","伫闻歌杕杜，凯入系名王。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-502f3a7b-a236-49e1-adab-ecb2994c9772","tags":[]},{"id":"poem-09006bda9570243703a82b83","title":"凤时春","author":"无名氏《张协状元》","dynasty":"元","verses":["张叶诗书遍历，困故乡功名未遂。","欲占春闱登科举，暂别爹娘，独自离乡里。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2450","tags":[]},{"id":"poem-090af4d43a353aa01f94c486","title":"石头滩作","author":"崔国辅","dynasty":"唐","verses":["怅矣秋风时，余临石头濑。","因高见远境，尽此数州内。","羽山数点青，海岸杂光碎。","离离树木少，漭漭湖波大。","日暮千里帆，南飞落天外。","须臾遂入夜，楚色有微霭。","寻远迹已穷，遗荣事多昧。","一身犹未理，安得济时代。","且泛朝夕潮，荷衣蕙为带。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-8a71bbdb-daeb-496b-84f0-38dd78f8d49a","tags":[]},{"id":"poem-0916f7aa23636c45ba55ba00","title":"和前人韵  其二","author":"王柏","dynasty":"宋","verses":["庭前日日见兰芽，谁把青山特地遮。","雁影寂寥君又远，归期夜夜卜灯花。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-c851b010-ab63-4711-81c8-f9033cc4d81b","tags":[]},{"id":"poem-092a468c9d60cd9acb4ca9ae","title":"女冠子·露花烟草","author":"张泌","dynasty":"五代","verses":["露花烟草，寂寞五云三岛，春正深。","貌减潜消玉，香残尚惹襟。","竹疏虚槛静，松密醮坛阴。","何事刘郎去，信沉沉。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-4-juan.json#record-38","tags":[]},{"id":"poem-0933201e0fce122ca617d230","title":"贺新郎","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(净、丑)夜来因吃酒，大雪中跌倒孙兄，让他落后。","拿了他靴中两锭钞，又把玉环拐走。","怎知今日跌破，我两个如蓝提水走归家，篮内何曾有？干呕气，惹场羞。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1783","tags":[]},{"id":"poem-094d2d3cd8906ad8e31c0ea8","title":"洁泉","author":"曾协","dynasty":"宋","verses":["绝爱泓然一鉴渟，肯教尘土犯清泠。","祇缘较德先生似，不为争名陆羽经。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-7c46f7ff-3d28-4321-83ff-67978ab4df7a","tags":[]},{"id":"poem-0950d18438707b7d4075d850","title":"与弟渤新罗劒歌","author":"李涉","dynasty":"唐","verses":["我有神劒异人与，暗中往往精灵语。","识者知从东海来，来时一夜因风雨。","长河临晓北斗残，秋水露背青螭寒。","昨夜大梁城下宿，不借𨁂跌光颜看。","刃边飒飒尘沙缺，瘢痕半是蛟龙血。","雷焕张华久已无，沉冤知向何人说。","我有爱弟都九江，一条直气今无双。","青光好去莫惆怅，必斩长鲸须少壮。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-88882037-a112-4b54-b424-93fe286f92bf","tags":[]},{"id":"poem-0951087643d1c48cf897f0b7","title":"阮郎归·摘山初制小龙团","author":"黄庭坚","dynasty":"宋","verses":["摘山初制小龙团。","色和香味全。","碾声初断夜将阑。","烹时鹤避烟。","消滞思，解尘烦。","金瓯雪浪翻。","只愁啜罢水流天。","馀清搅夜眠。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-752","tags":[]},{"id":"poem-095137e41c49e43813bac041","title":"牧童词","author":"李涉","dynasty":"唐","verses":["朝牧牛，牧牛下江曲。","夜牧牛，牧牛度村谷。","荷蓑出林春雨细，芦管卧吹莎草绿。","乱插蓬蒿箭满腰，不怕猛虎欺黄犊。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-6ff463a1-0105-4abb-a798-d6583a427af0","tags":["儿童","讽刺"]},{"id":"poem-0959d910e106cf85457541ba","title":"送李侍御赴安西","author":"高适","dynasty":"唐","verses":["行子对飞蓬，金鞭指铁骢。","功名万里外，心事一桮中。","虏障燕支北，秦城太白东。","离魂莫惆怅，看取宝刀雄。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c46a848d-86bf-4e2e-9ffc-442759ddfa7a","tags":["送别","壮志","惜别"]},{"id":"poem-095aa19d1e7c66891ed160c9","title":"前腔","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["我闻知做会，特来随喜。","馒头素食多多与，若还不与我自入斋厨。","(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-5204","tags":[]},{"id":"poem-0960a6dfdccd80f751e5135b","title":"遭田父泥饮美严中丞","author":"杜甫","dynasty":"唐","verses":["步屧随春风，邨邨自花柳。","田翁逼社日，邀我尝春酒。","酒酣夸新尹，畜眼未见有。","回头指大男，渠是弓弩手。","名在飞骑籍，长番岁时久。","前日放营农，辛苦救衰朽。","差料死则已，誓不举家走。","今年大作社，拾遗能住否。","叫妇开大缾，盆中为吾取。","感此气扬扬，须知风化首。","语多虽杂乱，说尹终在口。","朝来偶然出，自卯将及酉。","久客惜人情，如何拒邻叟。","高声索果栗，欲起时被肘。","指挥过无礼，未觉邨野丑。","月出遮我留，仍嗔问升斗。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-6c49fcc2-e014-4a5f-8b7b-bc592de83062","tags":["叙述","写人","政治","农民","写人诗"]},{"id":"poem-0960fa5944c13730c568ad8e","title":"夜闻回雁","author":"司空曙","dynasty":"唐","verses":["雁响天边过，高高望不分。","飕飗传细雨，嘹唳隔长云。","散向谁家尽，归来几客闻。","还将今夜意，西海话苏君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-ed7ad319-24c2-47d1-86be-f99ec92feccc","tags":[]},{"id":"poem-09616a5f304629f0008157af","title":"终风","author":"佚名","dynasty":"先秦","verses":["终风且暴，顾我则笑，谑浪笑敖，中心是悼。","终风且霾，惠然肯来，莫往莫来，悠悠我思。","终风且曀，不日有曀，寤言不寐，愿言则嚏。","曀曀其阴，虺虺其雷，寤言不寐，愿言则怀。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-29","tags":[]},{"id":"poem-0965e588bcaa68bc6085d736","title":"秋霁·江水苍苍","author":"史达祖","dynasty":"宋","verses":["江水苍苍，望倦柳愁荷，共感秋色。","废阁先凉，古帘空暮，雁程最嫌风力。","故园信息。","爱渠入眼南山碧。","念上国。","谁是、脍鲈江汉未归客。","还又岁晚，瘦骨临风，夜闻秋声，吹动岑寂。","露蛩悲、清灯冷屋，翻书愁上鬓毛白。","年少俊游浑断得。","但可怜处，无奈苒苒魂惊，采香南浦，翦梅烟驿。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-186","tags":["宋词三百首"]},{"id":"poem-096a724576849981c8aa9963","title":"别房太尉墓","author":"杜甫","dynasty":"唐","verses":["他乡复行役，驻马别孤坟。","近泪无干土，低空有断云。","对碁陪谢傅，把劒觅徐君。","唯见林花落，鸎啼送客闻。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-c19e64b1-604b-40b7-9e41-6ef57b9c6f7b","tags":["唐诗三百首","忧国忧民","感伤","五言律诗","悼亡"]},{"id":"poem-097887f792976963ed1abd7c","title":"别李谱","author":"赵嘏","dynasty":"唐","verses":["尊前路映暮尘红，池上琴横醉席风。","今日别君如别鹤，声容长在楚弦中。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-c949afb6-9040-48f8-8007-facc32e766d1","tags":[]},{"id":"poem-098875b8388e400037c56a93","title":"次韵林子长计使","author":"陈造","dynasty":"宋","verses":["林侯上州麾，便饫大官饭。","左淮鱼稻供，顾肯回一眄。","待人均待士，乐易屏崖岸。","悬知讫民庸，功倍而事半。","淮乡旧乐土，兼有齐俗缓。","顷来南北杂，颇复烦城旦。","要须禁夺攘，立可息愁叹。","为公泚银笔，攘袂歌粲晏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-355466c1-1987-4a28-9af5-0529f0b75dc9","tags":[]},{"id":"poem-098d66beb74a7aca3678f2dc","title":"游小园不值","author":"叶绍翁","dynasty":"宋","verses":["应嫌屐齿印苍苔，十扣柴扉九不开。","春色满园关不住，一枝红杏出墙来。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-遊小園不值","tags":[]},{"id":"poem-098e9ba3dba20abdf487b220","title":"麻婆子","author":"萧德祥《小孙屠》","dynasty":"元","verses":["对景对景空题恨，赢得闷上心。","止愁止愁青春过，年华暗逐人。","殷勤回首问东君：桃花开谢逢春，怕奴容颜老，何时遇个人？。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8574","tags":[]},{"id":"poem-09900d413564ca563d68beef","title":"游麻姑山二首  其一","author":"李纲","dynasty":"宋","verses":["鲁公辞翰勒山巅，骾峭风姿亦喜僊。","假道来游非偶尔，追寻遗迹更茫然。","野花幽草堪成梦，老鹤乔松不记年。","谁谓瑶台无路到，月明风露正涓涓。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-c3521efb-2a2c-4932-b256-53978b2b5aaf","tags":[]},{"id":"poem-099496e290655bc56bd18310","title":"蝶恋花·遥夜亭皋闲信步","author":"李煜","dynasty":"五代","verses":["遥夜亭皋闲信步。","乍过清明，早觉伤春暮。","数点雨声风约住，朦胧淡月云来去。","桃李依依春暗度。","谁在秋千，笑里低低语？","一片芳心千万绪，人间没个安排处。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-14","tags":[]},{"id":"poem-099b9df87e4296a9e1204dfc","title":"鹊踏枝・蝶恋花·斜日平山寒已薄","author":"宝月","dynasty":"宋","verses":["斜日平山寒已薄。","雪过松梢，犹有残英落。","晚色际天天似幕。","一尊先与东风约。","邀得红梅同宴乐。","酒面融春，春满纤纤萼。","客意为伊浑忘却。","归船且傍花阴泊。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-855","tags":[]},{"id":"poem-09b3d44dc27da0440d9b1313","title":"横吹曲辞 出塞 一","author":"王昌龄","dynasty":"唐","verses":["秦时明月汉时关，万里长征人未还。","但使龙城飞将在，不教胡马度阴山。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-de6b7e3d-03cd-4daa-bdc2-7fb820fda441","tags":["唐诗三百首","战争","写景","忧国忧民","爱国","乐府","山","边塞"]},{"id":"poem-09b6b166f96a9cae421c7987","title":"献刘济","author":"李益","dynasty":"唐","verses":["草绿古燕州，莺声引独游。","雁归天北畔，春尽海西头。","向日花偏落，驰年水自流。","感恩知有地，不上望京楼。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-2ece861e-f4da-4663-9ca7-22ed69e049dd","tags":[]},{"id":"poem-09c04de4208281083b12d158","title":"江南春","author":"杜牧","dynasty":"唐","verses":["千里莺啼绿映红，水村山郭酒旗风。","南朝四百八十寺，多少楼台烟雨中。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-江南春","tags":[]},{"id":"poem-09c5d3b733fe9977161e7aed","title":"人生叹","author":"赵崇嶓","dynasty":"宋","verses":["壮老互沦谢，百年如奔霆。","竞将无穷忧，劳此有尽形。","生时一幻化，死即归杳冥。","亦有贤达人，视死如未生。","亦有醉梦人，既死心未平。","逆旅朝暮闲，八风无时停。","扰扰安足计，熙然慰吾情。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-2ae54016-1540-427f-81f1-310b8abd9c29","tags":[]},{"id":"poem-09c5ee4bf0e7e9fe16dfa9b9","title":"途中寄徐录事","author":"高适","dynasty":"唐","verses":["落日风雨至，秋天鸿雁初。","离忧不堪比，旅馆复何如。","君又几时去，我知音信疎。","空多箧中赠，长见右军书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-70c1e034-056a-445d-bff6-9afa97a32ef0","tags":[]},{"id":"poem-09c9779e05e01c59c174953d","title":"赉","author":"佚名","dynasty":"先秦","verses":["文王既勤止，我应受之。敷时绎思，我徂维求定。时周之命，于绎思。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-294","tags":[]},{"id":"poem-09cda831f4b1560e75c64062","title":"题城南书院三十四咏  其二","author":"张栻","dynasty":"宋","verses":["新竹成林蕉叶青，隔篱深处有蝉鸣。","晚凉更觉长堤静，自遶荷花待月明。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-8fbfdae9-9a7a-4e2e-8470-43e19a845db0","tags":[]},{"id":"poem-09d0ff402aa46362c0ed309f","title":"题周奉御","author":"马云奇","dynasty":"唐","verses":["明王道得腹心臣，百万人中独一人。","阶下往来三迳迹，门前桃李四时春。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-18db8c47-4cb2-4d42-b518-4e16537fee34","tags":[]},{"id":"poem-09d26827eed00c51b42e07fa","title":"赠杜二拾遗","author":"高适","dynasty":"唐","verses":["传道招[提]客，诗书自讨论。","佛香时入院，僧饭屡过门。","听法还应难，寻经剩欲翻。","草玄今已毕，此外复何言。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-31bcaea7-a3c1-47a0-a1d3-eb91a703d1fb","tags":[]},{"id":"poem-09d6f1510be6df25dd79b878","title":"人月圆","author":"施惠《幽闺记》","dynasty":"元","verses":["(生)途路里，奔走流民拥，胆丧魂飞心惊恐。","(小旦)风吹雨湿衣襟重，止不住双双珠泪涌。","(合)行不上，惟闻得战鼓声振苍穹。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-2930","tags":[]},{"id":"poem-09e6b7f13c463b85ab9fd6fd","title":"送司空十四北游宋州","author":"张南史","dynasty":"唐","verses":["九拒危城下，萧条送尔归。","寒风吹画角，暮雪犯征衣。","道里犹成间，亲朋重与违。","白云愁欲断，看入大梁飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-721bea36-8cbd-4787-974d-23b4760c8b6b","tags":[]},{"id":"poem-09ef5fe54b3a446e1e29b48e","title":"思帝乡·云髻坠","author":"韦庄","dynasty":"五代","verses":["云髻坠，凤钗垂。","髻坠钗垂无力，枕函欹。","翡翠屏深月落，漏依依。","说尽人间天上，两心知。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-3-juan.json#record-14","tags":[]},{"id":"poem-0a03f599d3ed2e2f124a8ae9","title":"别牛郎中门馆","author":"赵嘏","dynasty":"唐","verses":["整襟收泪别朱门，自料难酬顾念恩。","招得片魂骑匹马，西风斜日入秋原。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-8bccb9f1-cffe-4671-a612-df0aa404ac82","tags":[]},{"id":"poem-0a07bcba80ba1a45f7e95c0b","title":"醉花间·休相问","author":"毛文锡","dynasty":"五代","verses":["休相问，怕相问，相问还添恨。","春水满塘生，㶉𫛶正相趁。","咋夜雨霏霏，临明寒一阵。","偏忆戍楼人，久绝边庭信。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-5-juan.json#record-21","tags":[]},{"id":"poem-0a0f4d3cb623fa300c9a856d","title":"子夜吴歌 秋歌","author":"李白","dynasty":"唐","verses":["长安一片月，万户捣衣声。","秋风吹不尽，总是玉关情。","何日平胡虏，良人罢远征。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-49194c4b-b775-4d21-a506-fc0a2ff308f1","tags":["思念","清商曲辞","妇女","秋天","唐诗三百首","乐府","月亮","闺怨"]},{"id":"poem-0a1051bd4c7de18075f09413","title":"春怨","author":"刘方平","dynasty":"唐","verses":["纱窗日落渐黄昏，金屋无人见泪痕。","寂寞空庭春欲晚，梨花满地不开门。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-fc1bc01d-c281-40fd-9e0d-4c484539e4ae","tags":["唐诗三百首","孤独","七言绝句","宫怨"]},{"id":"poem-0a11791453cd716a9ba91edd","title":"洋州三十景 二乐榭","author":"鲜于侁","dynasty":"宋","verses":["琴跻积翠外，𫄨结穹隆间。","轩槛最佳处，四顾惟江山。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-320c9ed0-59e5-47af-b287-f3626c67b1e9","tags":[]},{"id":"poem-0a19c5cba8a637ed885530be","title":"郊庙歌辞 武后明堂乐章 皇帝行","author":"武则天","dynasty":"唐","verses":["仰膺历数，俯顺讴歌。","远安迩肃，俗阜时和。","化光玉镜，讼息金科。","方兴典礼，永戢干戈。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-f5880c05-dba3-4d43-984e-11173bd45c36","tags":[]},{"id":"poem-0a19e6f1ea06ded57375ec43","title":"过高台获信老诗集","author":"张栻","dynasty":"宋","verses":["萧然僧榻碧云端，细读君诗夜未阑。","门外苍松霜雪里，比君佳处让高寒。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-0e4174ef-0b53-4066-a0b8-dd17e3098ca5","tags":[]},{"id":"poem-0a20406671d33abe33a38d56","title":"偈颂（幷序○序为南岳齐己撰） 三十九","author":"居遁","dynasty":"唐","verses":["万般施设不如常，又不惊人又久长。","如常恰似秋风至，无意凉人人自凉。","（又见《祖堂集》卷八）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-1b520b74-9df2-4855-a898-f4169b1c0fa9","tags":["衡山"]},{"id":"poem-0a3db373c0a293b88648faab","title":"赠邵尧夫","author":"司马光","dynasty":"宋","verses":["家虽在城阙，萧瑟似荒郊。","远去名利窟，自称安乐巢。","云归白石洞，鹤立碧松梢。","得丧非吾事，何须更解嘲。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-44da813b-b229-4495-8f30-57a5b56d70cb","tags":[]},{"id":"poem-0a4204f09aba1195ef879b0d","title":"翠屏峰","author":"陈岩","dynasty":"宋","verses":["削玉横陈开翠屏，东西有路总堪登。","向来同识春山面，犹有苍苍九节藤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-3641e0d0-dccb-4663-ac22-0b8f3d5ec774","tags":[]},{"id":"poem-0a4f5b0c897566a535b7ed49","title":"庆宫春・高阳台·双桨莼波","author":"姜夔","dynasty":"宋","verses":["双桨莼波，一蓑松雨，暮愁渐满空阔。","呼我盟鸥，翩翩欲下，背人还过木末。","那回归去，荡云雪、孤舟夜发。","伤心重见，依约眉山，黛痕低压。","采香径里春寒，老子婆娑，自歌谁答。","垂虹西望，飘然引去，此兴平生难遏。","酒醒波远，政凝想、明素袜。","如今安在，唯有阑干，伴人一霎。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-126","tags":["宋词三百首"]},{"id":"poem-0a59bb9ae3704bfe230c250a","title":"忆紫溪","author":"徐凝","dynasty":"唐","verses":["长忆紫溪春欲尽，千岩交映水回斜。","岩空水满溪自紫，水态更笼南烛花。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-277caaef-adac-43db-a554-c183d97cb795","tags":[]},{"id":"poem-0a606a71a3b3e777a460c4dd","title":"水调歌头·风卷暮云尽","author":"倪偁","dynasty":"宋","verses":["风卷暮云尽，镜净一天秋。","试把鹅黄新酒，细酌散闲愁。","西望群山千叠，眇眇飞鸿没处，爽气与俱浮。","且尽尊中绿，不用叹淹留。","对西风，歌妙曲，意绸缪。","万顷烟云奇变，所得过封侯。","何事苦萦名利，便合绿蓑青笠，投绂早归休。","他日君寻我，小艇钓寒流。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-461","tags":[]},{"id":"poem-0a8035acde6e9096928957fa","title":"一落索·眉共春山争秀","author":"周邦彦","dynasty":"宋","verses":["眉共春山争秀。","可怜长皱。","莫将清泪湿花枝，恐花也、如人瘦。","清润玉箫闲久。","知音稀有。","欲知日日倚阑愁，但问取、亭前柳。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-387","tags":[]},{"id":"poem-0a84d76008e749606cc7493f","title":"赠缘德","author":"曹翰","dynasty":"宋","verses":["二十年来访道人，奔波寒暑备艰辛。","谁知此日圆通会，便是今生出世因。","炉里有丹欣得遇，法中无语幸相亲。","如何至诀容传受，免向迷途强问津。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-d803c32e-0424-4f08-a004-d4cfd7262f88","tags":[]},{"id":"poem-0a8928fa348028aec384b155","title":"赋尚书","author":"太宗皇帝","dynasty":"唐","verses":["崇文时驻步，东观还停辇。","辍膳玩三坟，晖灯披五典。","寒心覩肉林，飞魄看沈湎。","纵情昏主多，克己明君鲜。","灭身资累恶，成名由积善。","既承百王末，战兢随岁转。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-69f09ef2-88a4-4fd3-979d-8cfb6541eb93","tags":[]},{"id":"poem-0a92e149167520b7db587cc7","title":"梦仙谣","author":"祝元膺","dynasty":"唐","verses":["蟾蜍夜作青冥烛，䗖𬟽晴为碧落梯。","好个分明天上路，谁教深入武陵溪。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-338e07c8-8635-4582-b65d-d2e188a1ca37","tags":[]},{"id":"poem-0a9395ddb0e7c36d962183f1","title":"鼓吹曲辞 雉子班","author":"李白","dynasty":"唐","verses":["辟邪伎作鼓吹惊，雉子班之奏曲成。","喔咿振迅欲飞鸣，扇锦翼，雄风生。","双雌同饮啄，趫悍谁能争。","乍向草中耿介死，不求黄金笼下生。","天地至广大，何惜遂物情。","善卷让天子，务光亦逃名。","所贵旷士怀，朗然合太清。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-0bfac3e5-6cc6-49c6-892e-e290aa5c5923","tags":[]},{"id":"poem-0a96721cb6479585ee10418b","title":"寄淮南幕中刘员外","author":"赵嘏","dynasty":"唐","verses":["郎官何逊最风流，爱月怜山不下楼。","三佐戎旃换朱绂，一辞兰省见清秋。","桂生岩石本潇洒，鹤到烟空更自由。","休向西斋久闲卧，满朝倾盖是依刘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-b7bbcd9e-7b1e-462e-984d-b5b3d94b9bf2","tags":[]},{"id":"poem-0aa096e53f7e83a410049fb3","title":"寄流人","author":"项斯","dynasty":"唐","verses":["毒草不曾枯，长添客健无。","雾开蛮市合，船散海城孤。","象迹频藏齿，龙涎远蔽珠。","家人秦地老，泣对日南图。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-2385716b-4311-4a91-98f8-2c1cc51f99d7","tags":[]},{"id":"poem-0aa2358bdea9f1b8cbea516d","title":"酬李仆射晚春见寄","author":"张籍","dynasty":"唐","verses":["戟户洞初晨，莺声雨后频。","虚庭清气在，众药湿光新。","鱼动芳池面，苔侵老竹身。","教铺尝酒处，自问探花人。","独此长多病，幽居欲过春。","今朝听高韵，忽觉离埃尘。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-50815b10-6ce9-4de8-8d1d-12321b2ae2e4","tags":[]},{"id":"poem-0aa7bf11f5636ed6b790fac3","title":"郊庙歌辞 享太庙乐章 和宁舞","author":"牛僧孺","dynasty":"唐","verses":["湜湜颀颀，融昭德辉。","不纽不舒，贯成九围。","武烈文经，敷施当宜。","纂尧付启，亿万熙熙。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-811d83e1-a2d7-4ffd-93b3-5705c81706e2","tags":[]},{"id":"poem-0aa99d54","title":"朝天子·咏喇叭","author":"王磐","dynasty":"明","verses":["喇叭，唢呐，曲儿小腔儿大。","官船来往乱如麻，全仗你抬声价。","军听了军愁，民听了民怕。","哪里去辨甚么真共假？","眼见的吹翻了这家，吹伤了那家，只吹的水尽鹅飞罢！"],"enabled":true,"collection":"历代名篇","source":"王磐《西楼乐府》散曲《朝天子·咏喇叭》。","tags":["散曲","讽喻"]},{"id":"poem-0ab2100ced83837858555247","title":"题泽翁小卷  其二","author":"王柏","dynasty":"宋","verses":["断岸江波阔，迢迢十里宽。","人烟藏处密，霁色媚寒滩。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.210000.json#record-531ae989-fedb-4ecd-8c30-4c93a79bcf2c","tags":[]},{"id":"poem-0ab2418c864304781c1781e4","title":"墙有茨","author":"佚名","dynasty":"先秦","verses":["墙有茨，不可扫也。中冓之言，不可道也。所可道也，言之丑也。","墙有茨，不可襄也。中冓之言，不可详也。所可详也，言之长也。","墙有茨，不可束也。中冓之言，不可读也。所可读也，言之辱也。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-45","tags":[]},{"id":"poem-0ab44293ac9743184b1135a4","title":"假乐","author":"佚名","dynasty":"先秦","verses":["假乐君子，显显令德，宜民宜人。受禄于天，保右命之，自天申之。","千禄百福，子孙千亿。穆穆皇皇，宜君宜王。不愆不忘，率由旧章。","威仪抑抑，德音秩秩。无怨无恶，率由群匹。受福无疆，四方之纲。","之纲之纪，燕及朋友。百辟卿士，媚于天子。不解于位，民之攸塈。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-248","tags":[]},{"id":"poem-0ab44a639aec9fae611f1079","title":"颜丞开炉","author":"释居简","dynasty":"宋","verses":["鳞差云母著书窗，软火深炉晓自粧。","篆恰才消余桂馥，手终不暖为枨香。","小中天地何妨大，闲里工夫不欠忙。","莫向市朝寻大隠，二松环水自汤汤。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-9dca188b-8cb7-4c13-9179-d77d9727df0b","tags":[]},{"id":"poem-0aba722b9c4236fb2bc1e953","title":"水调歌头·明月几时有","author":"苏轼","dynasty":"宋","verses":["明月几时有，把酒问青天。","不知天上宫阙，今夕是何年。","我欲乘风归去，又恐琼楼玉宇，高处不胜寒。","起舞弄清影，何似在人间。","转朱阁，低绮户，照无眠。","不应有恨，何事长向别时圆。","人有悲欢离合，月有阴晴圆缺，此事古难全。","但愿人长久，千里共婵娟。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-38","tags":["宋词三百首"]},{"id":"poem-0ac1c249d46631238cd5cac4","title":"感春","author":"张籍","dynasty":"唐","verses":["远客悠悠任病身，谢家池上又逢春。","明年各自东西去，此地看花是别人。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-ae0b6631-6a2b-478c-9f05-a8c1f2899e81","tags":[]},{"id":"poem-0ac223a8d0e9aff99e2f5b42","title":"次韵提舶见招","author":"王十朋","dynasty":"宋","verses":["江梅初破一阳天，诗句清新欲鬭妍。","呼我同来饮文字，定扶衰病到尊前。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-db29076f-6deb-42a6-bc7c-08897263d672","tags":[]},{"id":"poem-0ac77cfffda6c0e841a826b2","title":"·","author":"钱昱","dynasty":"唐","verses":["。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-eaaca141-386f-4d3c-beb7-4c8ea14686a9","tags":[]},{"id":"poem-0ace2c9678a814afc8872d60","title":"宋中十首 十","author":"高适","dynasty":"唐","verses":["阏伯去已久，高丘临道傍。","人皆有兄弟，尔独为参商。","终古犹如此，而今安可量。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-d3d18a80-f7b2-42d8-a910-ab4e51270e3a","tags":[]},{"id":"poem-0adc37992761eb420f8a02ba","title":"宫词二首 一","author":"张祜","dynasty":"唐","verses":["故国三千里，深宫二十年。","一声河满子，双泪落君前。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-d850db6a-e07b-4fee-b642-57a70bdbbed2","tags":["唐诗三百首","五言绝句","宫怨"]},{"id":"poem-0add41dab7b8bcde7617ce6f","title":"雨中花・夜行船·寄径濉阳","author":"葛立方","dynasty":"宋","verses":["寄径濉阳，陌上忽看，夭桃秾李争春。","又见楚宫，行雨洗芳尘。","红艳霞光夕照，素华琼树朝新。","为奇姿芳润，拟倩游丝，留住东君。","拾遗杜老，犹爱南塘，寄情萝薜山林。","争似此、花如姝丽，獭髓轻匀。","不数江陵玉杖，休夸花岛红云。","少须澄霁，一番清影，更待冰轮。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.8000.json#record-540","tags":[]},{"id":"poem-0ae72fb9a964994a600e2287","title":"春日对雨得情字","author":"王孝廉","dynasty":"唐","verses":["主人开宴在边听，客醉如泥等上京。","疑是雨师知圣意，甘滋芳润洒羁情。","（同前。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-66c39208-e3a3-4254-9f3a-05305aa66764","tags":[]},{"id":"poem-0af9beae06eb665594b86a72","title":"忆登栖霞寺峰","author":"李绅","dynasty":"唐","verses":["香印烟火息，法堂钟磬余。","纱灯耿晨焰，释子安禅居。","林叶脱红影，竹烟含绮疎。","星珠错落耀，月宇参差虚。","顾眺匪恣适，旷襟怀卷舒。","江海淼清荡，丘陵何所如。","滔滔可问津，耕者非长沮。","茅岭感仙客，萧园成古墟。","移步下碧峰，涉涧更踌躇。","乌噪啄秋果，翠惊衔素鱼。","回塘彩鹢来，落景标林箊。","漾漾棹翻月，萧萧风袭裾。","劳歌起旧思，戚叹竟难摅。","却数共游者，凋落非里闾。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-ef51a4e1-0a22-48a1-96ad-80463b0c8f08","tags":[]},{"id":"poem-0afcd1b01cd04e0f05635a5b","title":"同朱五题卢使君义井","author":"高适","dynasty":"唐","verses":["高义唯良牧，深仁自下车。","宁知凿井处，还是饮冰余。","地即泉源久，人当汲引初。","体清能鉴物，色洞每含虚。","上善滋来往，中和浃里闾。","济时应未竭，怀惠复何如。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-ff727be9-d103-4627-890a-94808ee85a13","tags":[]},{"id":"poem-0b05ae29158df172bed683f8","title":"红窗迥·几日来、真个醉","author":"周邦彦","dynasty":"宋","verses":["几日来、真个醉。","不知道、窗外乱红，已深半指。","花影被风摇碎。","拥春酲乍起。","有个人人，生得济楚，来向耳畔，问道今朝醒未。","情性儿、慢腾腾地。","恼得人又醉。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-486","tags":[]},{"id":"poem-0b13c936a61f0d9af71f1325","title":"李光道见过赠诗","author":"华镇","dynasty":"宋","verses":["高槐上拂青天面，枝疏不得惊禽恋。","槐下官曹何冷落，去马来牛色多倦。","春风绿杨暗虚室，秋雨苍苔锁深院。","三见墙头梅子花，一字不画尘侵砚。","宛如太古两相忘，况复飞盖追游宴。","有时独咏西园诗，想像清风情眷眷。","门前忽报华轩过，邂逅开怀如昔见。","目击便嗟相得晚，更仆清谈尽黄卷。","顾我迂疏何所取，似君秀颖迺可羡。","少壮应须努力时，人间岁月如流电。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-aa8dfbe9-5b46-4a5a-9b2d-c04e291f1ffa","tags":[]},{"id":"poem-0b1767d904af7d02b45c6461","title":"三一","author":"王梵志","dynasty":"唐","verses":["养儿从少打，（「少」，伯三五五八、伯三七一六、伯三六五六卷作「小」。","）莫道怜不笞。","长大欺父母，后回（一本作「悔」。","）定无鱼。","（一本作「疑」。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-ee4a0058-8dbe-444e-9e79-3f8750357df8","tags":[]},{"id":"poem-0b1a63f665d5a9ee0508a648","title":"题空山人石室","author":"崔峒","dynasty":"唐","verses":["早晚悟无生，头陀不到城。","云山知夏腊，猨鸟见修行。","地僻无溪路，人寻逐水声。","年年深谷里，谁识远公名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.15000.json#record-8da62a2e-2782-4b7a-80c7-45042284ffc2","tags":[]},{"id":"poem-0b211f4629901993e334c1f2","title":"冰赋附诗","author":"杨夔","dynasty":"唐","verses":["深山穷谷[凌]（陵）人凿，颁赐从来天下闻。","别有川池捐弃者，统思采斵献明君。","（《文苑英华》卷三八。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-1c463b1f-41b4-48c3-a94f-7145f702ff7e","tags":[]},{"id":"poem-0b286d2a2f640cc6cc20e5d8","title":"渡扬子江","author":"丁仙芝","dynasty":"唐","verses":["桂楫中流望，空波两岸明。","林开扬子驿，山出润州城。","海尽边阴静，江寒朔吹生。","更闻枫叶下，淅沥度秋声。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-渡揚子江","tags":[]},{"id":"poem-0b2d6e61523fc8fc1cf31d3f","title":"黄鹤楼","author":"崔颢","dynasty":"唐","verses":["昔人已乘白云去，此地空余黄鹤楼。","黄鹤一去不复返，白云千载空悠悠。","晴川历历汉阳树，春草萋萋鹦鹉洲。","日暮乡关何处是，烟波江上使人愁。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-2188f98e-d5f0-4740-b94b-e1497a3619ee","tags":["唐诗三百首","黄鹤楼","隋・唐・五代","七言律诗","八年级上册(课外)","写景","初中古诗","思乡","名楼、庙宇","怀古","带有地名","地名"]},{"id":"poem-0b2ea7f92ef591b995509326","title":"酬晦斋谢司直和子寿宫使赋归来望思之台","author":"释居简","dynasty":"宋","verses":["推恩保四海，寡恩徒自戕。","父兮不念子，悠悠我心伤。","父子至情天性也，戾岂自经沟渎者。","回天无药愈狂酲，朽索胡为羁六马。","邪心不作天不疑，皇恤江充刘屈牦。","灵修一悟倘可冀，抑免杀身伤父慈。","千秋一言机发弩，堕甑已非何所补。","归来望思兮胡不归，千古万古一抔土。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.180000.json#record-32c1f1e3-4bae-4f49-a0eb-f2dbf38d36f0","tags":[]},{"id":"poem-0b304391697a9fd91aafb948","title":"戏赠慎微寺主道安上座三僧正","author":"李德裕","dynasty":"唐","verses":["甘露洒空惟一味，旃檀移植自成薰。","遥知畅献分南北，应用调柔致六群。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-6b226b9c-55ba-4bac-ba7c-cd98fea6401e","tags":[]},{"id":"poem-0b426f469db6a0f286502752","title":"送史馆高员外使岭南","author":"徐铉","dynasty":"宋","verses":["东观时闲暇，还修喻蜀书。","双旌驰县道，百越从轺车。","桂蠹晨餐罢，贪泉访古初。","春江多好景，莫使醉吟疏。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-963b79a0-3c2d-4512-890c-c419c6a632d6","tags":[]},{"id":"poem-0b434a162cb317ecb2771138","title":"试周郎・诉衷情·乔家深闭郁金堂","author":"贺铸","dynasty":"宋","verses":["乔家深闭郁金堂。","朝镜事梅妆。","云鬟翠钿浮动，微步拥钗梁。","情尚秘，色犹庄。","递瞻相。","弄丝调管，时误新声，翻试周郎。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-872","tags":[]},{"id":"poem-0b437df807e058d70f01f4c2","title":"秋夜陪张丞相赵侍御游㴩湖二首 一","author":"尹懋","dynasty":"唐","verses":["熊轼巴陵地，鹢舟湘水浔。","江山与势远，泉石自幽深。","杳霭入天壑，冥茫见道心。","超然无俗事，清宴有空林。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-c86e65c7-7639-401b-a6e6-d02220a9c88b","tags":[]},{"id":"poem-0b445e3687f526c42b804c5d","title":"司理叔文和过万桥诗复用前韵","author":"王十朋","dynasty":"宋","verses":["少年一夕九起嗟，家贫亲老无生涯。","河东先生独青眼，慨然许我修通家。","三十年间同转首，王谢依然作甥舅。","时人咸笑孺子贫，杜老惟蒙丈人厚。","罢官闽峤初归来，登堂又荷倾金罍。","诗诵白圭感前事，情钟我辈衔余哀。","定向清朝力求退，呼宾剩设严冬鲙。","从公杖屦鹿岩前，明月清风赵欧会。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-d1adcb3b-6d4f-4ee5-93ea-dd401673068b","tags":[]},{"id":"poem-0b508b82ce473d79a0f3b66c","title":"木兰花・玉楼春·城上风光莺语乱","author":"钱惟演","dynasty":"宋","verses":["城上风光莺语乱。","城下烟波春拍岸。","绿杨芳草几时休，泪眼愁肠先已断。","情怀渐变成衰晚。","鸾鉴朱颜惊暗换。","昔年多病厌芳尊，今日芳尊惟恐浅。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-138","tags":["宋词三百首"]},{"id":"poem-0b5148a32f09f0268034c916","title":"惜奴娇","author":"高明《蔡伯喈琵琶记》","dynasty":"元","verses":["孩儿来，杏脸桃腮，又当有松筠节操，蕙兰襟怀。","闺中言语，不出阃阈之外。","老姥姥，不教孩儿伊之罪。","惜春，这风情今休再。","(合)记再来，但把不出闺门的，语言相戒。","(贴唱)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-4965","tags":[]},{"id":"poem-0b54165c350854d7a3eb583c","title":"送新罗使","author":"张籍","dynasty":"唐","verses":["万里为朝使，离家今几年。","应知旧行路，却上远归船。","夜泊避蛟窟，朝炊求岛泉。","悠悠到乡国，还望海西天。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-7b99f297-4701-4256-91bc-e33a5ac4b67c","tags":[]},{"id":"poem-0b5785a12de0a595dc2f1cdc","title":"河传·秋光向晚","author":"赵鼎","dynasty":"宋","verses":["秋光向晚。","叹羁游坐见。","年华将换。","一纸素书，拟托南来征雁。","奈雪深、天更远。","东窗皓月今宵满。","浅酌芳尊，暂倩嫦娥伴。","应念夜长，旅枕孤衾不暖。","便莫教、清影转。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.2000.json#record-955","tags":[]},{"id":"poem-0b61962d00783173ea10c9b1","title":"别董大二首 一","author":"高适","dynasty":"唐","verses":["十里黄云白日曛，北风吹雁雪纷纷。","莫愁前路无知己，天下谁人不识君。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-36d65b5a-7b4d-4b3d-a1b7-6fd144360f8f","tags":[]},{"id":"poem-0b70a38db6dd03ca301e55e0","title":"寿州裴中丞出柘枝","author":"张祜","dynasty":"唐","verses":["青娥十五柘枝人，玉鳯双翘翠帽新。","罗带却翻柔紫袖，锦靴前踏没红茵。","深情记处常低眼，急拍来时旋折身。","愁见曲终如梦觉，又迷烟水汉江滨。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d799a1de-5f30-47a3-8090-d735ccc9b90d","tags":[]},{"id":"poem-0b72dbb901a85bbe5d5a269f","title":"宫词  其四五","author":"张公庠","dynasty":"宋","verses":["上番宫女卷帘时，闪闪寒鸦拂晓啼。","才索赭迎催进辇，紫宸门外报班齐。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.30000.json#record-9df0cfdb-5327-424d-a86b-1950bd9845db","tags":[]},{"id":"poem-0b757a871c449dc19cf10398","title":"送履霜上人还金陵西山","author":"皎然","dynasty":"唐","verses":["携锡西山步绿莎，禅心未了奈情何。","湘宫水寺清秋夜，月落风悲松柏多。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-d956bc46-82d6-4c9b-9f8d-f936709f89f9","tags":[]},{"id":"poem-0b76d8e794c369bc1e9d1ea6","title":"浣溪沙·身向云山那畔行","author":"纳兰性德","dynasty":"清","verses":["身向云山那畔行，北风吹断马嘶声。","深秋远塞若为情。","一抹晚烟荒戍垒，半竿斜日旧关城。","古今幽恨几时平。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-172","tags":[]},{"id":"poem-0b776dd2abd76f17245931ec","title":"瑞鹤仙·晴丝牵绪乱","author":"吴文英","dynasty":"宋","verses":["晴丝牵绪乱。","对沧江斜日，花飞人远。","垂杨暗吴苑。","正旗亭烟冷，河桥风暖。","兰情蕙盼。","惹相思、春根酒畔。","又争知、吟骨萦销，渐把旧衫重翦。","凄断。","流红千浪，缺月孤楼，总难留燕。","歌尘凝扇。","待凭信，拌分钿。","试挑灯欲写，还依不忍，笺幅偷和泪卷。","寄残云、剩雨蓬莱，也应梦见。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-4","tags":["宋词三百首"]},{"id":"poem-0b783b73fb54fc7ae460ab51","title":"贺雨拜表","author":"林之奇","dynasty":"宋","verses":["群云雨事毕，振旅不复阵。","扫天无一尘，千里还绿润。","晨朝大明贺，沙路万蹄印。","朝元泛翠瓦，佳气去人近。","颇闻避斧扆，侑膳彻龙笋。","愿君爱物心，从此至尧舜。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-c0d91c2b-8410-40cb-8abd-0994a4afa203","tags":[]},{"id":"poem-0b86c8553a0adcc6ebaaa02a","title":"前腔","author":"刘唐卿《白兔记》","dynasty":"元","verses":["(生)刘智远得罪自知，因贫困多蒙周济。","有缘千里能相会，这恩德何日忘之？(合前)。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-8861","tags":[]},{"id":"poem-0b921aa01cea5ae216e74ddd","title":"山居诗  其二","author":"释延寿","dynasty":"宋","verses":["古树交盘簇径深，阒无人到为难寻。","祇和算计千般事，谁解消停一点心。","冰锁瀑声中夜断，云吞岳影半天沈。","寒灯欲绝禅初起，透牖疏风触短襟。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-ba99895f-ada2-43b1-bfd9-c79bd1d73e08","tags":[]},{"id":"poem-0b943b5f788abdd3a0fa11e6","title":"修竹百竿才欣种植佳篇五首旋辱咏歌若无还答之言是阙唱酬之礼恭依来韵以导鄙怀调下才卑岂逃嗤诮  其四","author":"李昉","dynasty":"宋","verses":["青青鬰鬰影疏疏，碧嶂移根到我居。","为爱绿阴时遣扫，恐伤新笋不教锄。","勾牵好鸟啼幽槛，摇摆清风上碧虚。","栽得此君知有幸，入他仙客咏吟余。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-e05dc266-8df5-408c-8a15-f1a6615a03ed","tags":[]},{"id":"poem-0b960f83bfdc5683e7d81081","title":"谴谪康州先寄弟渤","author":"李涉","dynasty":"唐","verses":["唯将直道信苍苍，可料无名抵宪章。","阴隲却应先有谓，已交鸿鴈早随阳。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-36062ad8-6800-4112-bee0-39b859d791a8","tags":[]},{"id":"poem-0b98f66efba4b6748460f1d3","title":"诗品二十四则 自然","author":"司空图","dynasty":"唐","verses":["俯拾即是，不取诸邻。","俱道适往，著手成春。","如逢花开，如瞻岁新。","真予不夺，强得易贫。","幽人空山，过水采苹。","薄言情晤，悠悠天钧。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-026db8ed-2a59-495f-a4e5-25556b033624","tags":[]},{"id":"poem-0b997324a3f36645760940be","title":"和友人喜相遇十首 六","author":"李咸用","dynasty":"唐","verses":["已向丘门老此躯，可堪空作小人儒。","吟中景象千般有，书外囊装一物无。","润屋必能知早散，辉山应是不轻沽。","短衣宁倦重修谒，谁识高阳旧酒徒。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-b34f8cde-a7c4-4ea5-b692-f75855cb5511","tags":[]},{"id":"poem-0b9cbd3b824ad9bd0a8b206d","title":"浣溪沙·红日已高三丈透","author":"李煜","dynasty":"五代","verses":["红日已高三丈透，金炉次第添香兽。","红锦地依随步皱。","佳人舞点金钗溜，酒恶时拈花蕊嗅。","别殿遥闻箫鼓奏。"],"enabled":true,"collection":"南唐二主词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/nantang/poetrys.json#record-19","tags":[]},{"id":"poem-0ba92383b3bbe445637bd6a4","title":"忆江南弟","author":"孟郊","dynasty":"唐","verses":["白首眼垂血，望尔唯梦中。","筋力强起时，魂魄犹在东。","眼光寄明星，起来东望空。","望空不见人，江海波无穷。","衰老无气力，呼叫不成风。","孑然忆忆言，落地何由通。","常师共被教，竟作生离翁。","生离不可诉，上天何曾聪。","未忍对松栢，自鞭残朽躬。","自鞭亦何益，知教非所崇。","努力拄杖来，余活与尔同。","不然死后耻，遗死亦有终。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.20000.json#record-dddb79fa-7c1c-4854-9738-3d4de5dbfcce","tags":[]},{"id":"poem-0bab3a4c6cadc422b0b58bb9","title":"新嫁娘词三首 三","author":"王建","dynasty":"唐","verses":["三日入厨下，洗手作羹汤。","未谙姑食性，先遣小姑尝。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-efaaa86e-5628-40d3-a137-1ae8fcbe41b8","tags":["唐诗三百首","新婚","五言绝句","女子","生活"]},{"id":"poem-0bad3e056eac34b6d274845c","title":"题天回驿","author":"蜀太妃徐氏","dynasty":"唐","verses":["翠驿红亭近玉京，梦魂犹是在青城。","比来出看江山景，却被江山看出行。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-6a2e95e9-217d-43dc-8056-7e0e9a44358a","tags":[]},{"id":"poem-0bb3faa93f3946aa615b0485","title":"婆罗门引·风涟乱翠","author":"吴文英","dynasty":"宋","verses":["风涟乱翠，酒霏飘汗洗新妆。","幽情暗寄莲房。","弄雪调冰重会，临水暮追凉。","正碧云不破，素月微行。","双成夜笙，断旧曲、解明珰。","别有红娇粉润，初试霓裳。","分莲调郎。","又拈惹、花茸碧唾香。","波晕切、一盼秋光。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.6000.json#record-483","tags":[]},{"id":"poem-0bb64d13e2f3e95a2c9d74f2","title":"铜雀妓","author":"皎然","dynasty":"唐","verses":["强开尊酒向陵看，忆得君王旧日懽。","不觉余歌悲自断，非关艳曲转声难。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-a6df100f-c72d-43ce-ab45-c264abb61961","tags":[]},{"id":"poem-0bc737fd95a3939d92e96e22","title":"竹枝歌  其九","author":"孙嵩","dynasty":"宋","verses":["峡山削出青嵯峨，峡水匀成绿不波。","顿平山林未能得，奈此猿声朝夕何。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-803e5005-b7f6-4b6d-be7b-ef66316c65fa","tags":[]},{"id":"poem-0bd30a96de785f5eda9ea387","title":"酬彭伉","author":"李涉","dynasty":"唐","verses":["公孙阁里见君初，衣锦南归二十余。","莫叹屈声犹未展，同年今日在中书。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-cf80c19d-9ccb-4870-a50b-6653f4c33241","tags":[]},{"id":"poem-0bd76998e931485784d1fffe","title":"蓦山溪·楼前疏柳","author":"周邦彦","dynasty":"宋","verses":["楼前疏柳，柳外无穷路。","翠色四天垂，数峰青、高城阔处。","江湖病眼，偏向此山明，愁无语。","空凝伫。","两两昏鸦去。","平康巷陌，往事如花雨。","十载却归来，倦追寻、酒旗戏鼓。","今宵幸有，人似月婵娟，霞袖举。","杯深注。","一曲黄金缕。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.4000.json#record-517","tags":[]},{"id":"poem-0bdc9cf5e2190a4cfa4838d2","title":"九歌·山鬼","author":"屈原","dynasty":"先秦","verses":["若有人兮山之阿，被薜荔兮带女萝。","既含睇兮又宜笑，子慕予兮善窈窕。","乘赤豹兮从文狸，辛夷车兮结桂旗。","被石兰兮带杜衡，折芬馨兮遗所思。","余处幽篁兮终不见天，路险难兮独后来。","表独立兮山之上，云容容兮而在下。","杳冥冥兮羌昼晦，东风飘兮神灵雨。","留灵修兮憺忘归，岁既晏兮孰华予。","采三秀兮于山间，石磊磊兮葛蔓蔓。","怨公子兮怅忘归，君思我兮不得闲。","山中人兮芳杜若，饮石泉兮荫松柏。","君思我兮然疑作。","雷填填兮雨冥冥，猿啾啾兮狖夜鸣。","风飒飒兮木萧萧，思公子兮徒离忧。"],"enabled":true,"collection":"楚辞","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/楚辞/chuci.json#record-9","tags":[]},{"id":"poem-0be01b090b4aa033e466b831","title":"采桑子·拨灯书尽红笺也","author":"纳兰性德","dynasty":"清","verses":["拨灯书尽红笺也，依旧无聊。","玉漏迢迢，梦里寒花隔玉箫。","几竿修竹三更雨，叶叶萧萧。","分付秋潮，莫误双鱼到谢桥。"],"enabled":true,"collection":"纳兰词","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/纳兰性德/纳兰性德诗集.json#record-47","tags":[]},{"id":"poem-0be4d7f9eb7519260b2be4c4","title":"兵要望江南 占梦第二十五（京本列第十三○九首） 四","author":"易静","dynasty":"唐","verses":["将军梦，打（辛本、川本、京本作「大」）鼓大声鸣。","小鼓小声（京本作「鸣」）军小胜，不鸣固守莫先（京本作「前」）征，胜负取其声。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-7a428e38-c7a5-472b-8568-8901400fffbf","tags":[]},{"id":"poem-0be7ec876f93c9defa9f4382","title":"一○九","author":"王梵志","dynasty":"唐","verses":["城外土馒头，馅草在城里。","一人吃一个，莫嫌没滋味。","（此诗又见《冷斋夜话》卷十、《苕溪渔隐丛话前集》卷五六、《诗话总龟》卷三九引《东坡诗话》、《云卧纪谭》等书。","）（以上二首黄庭坚引梵志诗。","）（〖1〗案以上诸诗，郑振铎辑本并收之。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-d710a6df-6ef0-40d9-8280-875f4ce41edc","tags":[]},{"id":"poem-0be7ee2a8199eecc9ba90213","title":"十二月","author":"杨景贤","dynasty":"元","verses":["他那里呱呱叫吼，我这里急急抽头。","将匣子轻抬手，近着这沙岸汀洲。","哭声哀猿闻肠断，匣影孤鱼见应愁。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-7953","tags":[]},{"id":"poem-0be8011e3e2ce44d7d1c19ea","title":"金谷园","author":"李咸用","dynasty":"唐","verses":["石家旧地聊登望，宠辱从兹信可惊。","鸟度野花迷锦障，蝉吟古树想歌声。","虽将玉貌同时死，却羡苍头此日生。","多积黄金买刑戮，千秋成得绿珠名。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-69d79950-c3ac-4dd4-bb8e-9faa98b49c6a","tags":[]},{"id":"poem-0beaf06d4f2ba7ab01c94966","title":"山居诗  其二四","author":"释延寿","dynasty":"宋","verses":["危岭如登百尺楼，千般异景望中收。","浮生但向忙时过，万事须从静处休。","道直岂教容鬼怪，理平唯祇使魔愁。","空门莫说无知己，满目松萝是我俦。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.0.json#record-f11eea14-3026-41e3-a3ad-dc07b22de2cf","tags":[]},{"id":"poem-0bf29fd8fc6b112f43ce8f22","title":"敦煌廿咏（并序） 十九、凿壁井咏","author":"敦煌人作品[一]","dynasty":"唐","verses":["尝闻凿壁井，兹水最为灵。","色带三春渌，芳传一味清。","玄言称上善，图录著高名。","德重胜铢两，诸流量[三六]且轻。","。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-694dc15d-1d26-45cb-96d4-7ec6c4c2d9d7","tags":[]},{"id":"poem-0bf73a3f08324cd3538d1c7e","title":"题西明寺攻文僧林复上人房","author":"李洞","dynasty":"唐","verses":["谁寄湘南信，阴窗砚起津。","烧痕碑入集，海角寺留真。","楼憩长空鸟，钟惊半阙人。","御沟圆月会，似在草堂身。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.40000.json#record-28e73374-417f-47d0-b8c8-f3b625bacdac","tags":[]},{"id":"poem-0bf76fd4e71eeb5aa428fc4f","title":"同崔员外秋宵寓直","author":"王维","dynasty":"唐","verses":["建礼高秋夜，承明候晓过。","九门寒漏彻，万井曙钟多。","月迥藏珠斗，云消出绛河。","更慙衰朽质，南陌共鸣珂。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-ba54ac5b-a131-4af6-a7e0-938db34b82fb","tags":[]},{"id":"poem-0bfa17dcdac14ed9483d727e","title":"秋日毘陵南寺送潘述之扬州","author":"皎然","dynasty":"唐","verses":["孤客秋易伤，嘶蝉静仍续。","佳晨亦已屡，欢会常不足。","禅地非路岐，我心岂羁束。","情生远别时，坐恨清景促。","望中千里隔，暮归西山曲。","萧条月中道，彩蒨原上绿。","不见同心人，幽怀增踯躅。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-eacea3d6-d9cd-4f35-836d-8b27480a3fc2","tags":[]},{"id":"poem-0bfc1c455f2177e88374caa9","title":"遣悲怀三首 二","author":"元稹","dynasty":"唐","verses":["昔日戏言身后意，今朝皆到眼前来。","衣裳已施行看尽，针线犹存未忍开。","尚想旧情怜婢仆，也曾因梦送钱财。","诚知此恨人人有，贫贱夫妻百事哀。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-ea3f91f0-487e-4df7-826a-3692ef82e64d","tags":["唐诗三百首","思念","追忆","悼亡","七言律诗"]},{"id":"poem-0c016d843433d16ac2b795bc","title":"省超偈（题拟）","author":"道怤","dynasty":"唐","verses":["省超之时不守住，更须腾身后前机。","太虚不㝵金乌运，霄汉宁妨玉兔飞。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-14eb8222-c819-419d-9d01-405c370edda5","tags":[]},{"id":"poem-0c05966f871a1c2f2ec79a10","title":"江梅","author":"曾协","dynasty":"宋","verses":["北风号乔林，万象无容姿。","高标自有时，正与冰雪宜。","老干俨枯木，疎花粲横枝。","刻玉费天巧，不为俗眼窥。","托质在空谷，清高终见知。","论功鼎鼐间，枝头子离离。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-540f65aa-1d5c-4013-8bbd-f59ebbe8612e","tags":[]},{"id":"poem-0c0816fb336b3e42ada0abd4","title":"宿龙兴寺","author":"綦毋潜","dynasty":"唐","verses":["香刹夜忘归，松清古殿扉。","灯明方丈室，珠系比丘衣。","白日传心净，青莲喻法微。","天花落不尽，处处鸟衔飞。"],"enabled":true,"collection":"千家诗","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/蒙学/qianjiashi.json#record-宿龍興寺","tags":[]},{"id":"poem-0c0e48d750d67cd44051d772","title":"送僧归南康","author":"贯休","dynasty":"唐","verses":["壳壳学得律，还乡见苦情。","远思芳草盛，不入楚山行。","帆入汀烟健，经吟戍月清。","到乡同学辈，应到赣江迎。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-52cc3857-5a5a-48f6-ae74-643bcdf26fe1","tags":[]},{"id":"poem-0c1416fbf2c7d6a2743b90ec","title":"渡汉江","author":"宋之问","dynasty":"唐","verses":["岭外音书断，经冬复历春。","近乡情更怯，不敢问来人。"],"enabled":true,"collection":"唐诗三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/唐诗三百首.json#record-eb9530d2-e4c7-4c34-9214-06c28ca586bf","tags":["唐诗三百首","五言绝句","思乡","渡江"]},{"id":"poem-0c187c144d2f4d9f49d6fcb5","title":"偈颂三十首  其一一","author":"释印肃","dynasty":"宋","verses":["若无一切心，何用一切法。","佛说一切法，为除一切心。","若人解实相，于中无虚诳。","说与不说同，是即名最上。","实相未全融，语默空花同。","而复结空果，后进不能通。","何故不能通，缘师指落空。","依妄不归实，师子堕邪宗。","二妄相依堕，带累千万个。","因一人道虚，万类皆招祸。","不了却自心，只管说他过。","将谓佛法僧，也似陈行货。","倒床吃不得，苦痛忍难过。","晓夕无把捉，又见火轮磨。","始悔我自错，无福转加祸。","未得将为得，未证将为证。","妄想一刹那，果招沙劫病。","皆是自欺心，不依佛慧命。","六度未能圆，五戒犹未定。","口说一切无，贪嗔转增盛。","人问道如何，胡应全无性。","此不见性种，三界魔民虫。","众生若遭遇，万劫堕贫穷。","自坏他亦坏，自聋他亦聋。","自堕彼亦堕，自空彼亦空。","究竟还如佛，万像一镜中。","若能如是解，可表警凡笼。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-de44d2d1-27a0-4ae9-b3cd-8eb38bf878cb","tags":[]},{"id":"poem-0c223910f82a0fb33136d68e","title":"十二咏 荔枝亭","author":"李纲","dynasty":"宋","verses":["平生最赏荔枝名，手植芳根傍草亭。","嘉木亦知人意重，著花不待一周星。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.90000.json#record-8fb50fb5-634f-48bd-8703-582f27774c8f","tags":[]},{"id":"poem-0c35ad35cda407bedb10afbd","title":"游干明分韵得山字","author":"陈造","dynasty":"宋","verses":["竹风清如水，浣我尘埃颜。","老禅贫无锥，小破蔬笋悭。","短辕下鸱夷，共此半日闲。","住笔讯鶑燕，把杯属江山。","老夫病止饮，苦语涩莫删。","揆予郊岛寒，著君季孟间。","江柳未遽折，园花且同攀。","后夜短亭梦，漫寄东风还。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.150000.json#record-bce11135-6a1c-4705-91aa-85a72ccb2202","tags":[]},{"id":"poem-0c38020388f0dade80878089","title":"赠金励睡诗 二","author":"陈抟","dynasty":"唐","verses":["至人本无梦，其梦本游仙。","真人本无睡，睡则浮云烟。","炉里近（《事今类聚》作「名」）为药，壶中别有天。","欲知睡梦里，人间第一玄。","（《增修诗话总龟》卷四六引《翰府名谈》、《事文类聚后集》卷二一。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-1c20d9ae-d642-45e3-baf2-5a3662cb722a","tags":[]},{"id":"poem-0c3d7737d9e2cbc8a0c6f67a","title":"阆水歌","author":"杜甫","dynasty":"唐","verses":["嘉陵江色何所似，石黛碧玉相因依。","正怜日破浪花出，更复春从沙际归。","巴童荡桨攲侧过，水鸡衔鱼来去飞。","阆中胜事可肠断，阆州城南天下稀。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-b0d04448-935e-4e7a-ad7e-9a69c31b0ad7","tags":["抒情","地方","写景","赞美"]},{"id":"poem-0c449648a1038a8203f4f607","title":"鼓吹曲辞 鼓吹铙歌 晋阳武","author":"柳宗元","dynasty":"唐","verses":["晋阳武，奋义威。","炀之渝，德焉归。","氓毕屠，绥者谁。","皇烈烈，专天机。","号以仁，扬其旗。","日之升，九土晞。","斥田圻，流洪辉。","有其二，翼余隋。","斮枭骜，连熊螭。","枯以肉，勍者羸。","后土荡，玄穹弥。","合之育，莽然施。","惟德辅，庆无期。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-df56529b-2c90-46a3-baf8-223faff1c1af","tags":[]},{"id":"poem-0c45f80e3a43629b6dad4e00","title":"重葺前堂榜曰学易景亮六丈宠惠新诗谨赋二诗上谢  其一","author":"刘跂","dynasty":"宋","verses":["并舍荒芜三四寻，稍营轩槛便幽深。","已将种木待休影，未暇摊书聊洗心。","投老篇章愁脉脉，随缘香火静愔愔。","从今扫洒供鸡黍，知有高人肯见临。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.60000.json#record-637e348e-27d9-4951-8dc4-13e35c123f06","tags":[]},{"id":"poem-0c4608d50542c4b006e8a7f4","title":"古塞曲三首 一","author":"贯休","dynasty":"唐","verses":["单于烽火动，都护去天涯。","别赐黄金甲，亲临白玉除。","塞垣须静谧，师旅审安危。","定远条支宠，如今胜古时。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-4f49601d-f757-4cd2-b8f0-4b8d6f05bb9d","tags":[]},{"id":"poem-0c48cc3335cd63ef893bf289","title":"答师静","author":"小静","dynasty":"唐","verses":["幻人兴幻幻轮围，幻业能招幻所治。","不了幻生诸幻苦，觉知如幻幻无为。","（同前。","）。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.55000.json#record-8072158c-1327-4ca8-ab6b-9c4228307885","tags":[]},{"id":"poem-0c4b61ff582593557cb47497","title":"峡山亭月夜独宿对樱桃花有怀伊川别墅","author":"李德裕","dynasty":"唐","verses":["皎月照芳树，鲜葩含素辉。","愁人惜春夜，达曙想岩扉。","风静阴满砌，露浓香入衣。","恨无金谷妓，为我奏思归。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.25000.json#record-22179021-1fac-45c0-9764-8f1f76da456d","tags":[]},{"id":"poem-0c4e9d75e0f9040a88e26f62","title":"菩萨蛮·郁孤台下清江水","author":"辛弃疾","dynasty":"宋","verses":["郁孤台下清江水。","中间多少行人泪。","西北是长安。","可怜无数山。","青山遮不住。","毕竟江流去。","江晚正愁予。","山深闻鹧鸪。"],"enabled":true,"collection":"宋词三百首","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/宋词三百首.json#record-211","tags":["宋词三百首"]},{"id":"poem-0c5e4c3a0b704de425f20f8b","title":"闺情（为落殊蕃陈上相知人） 闺情 二","author":"高适","dynasty":"唐","verses":["不须推道委人猜，只是君心自不开。","今夜闺门凭莫闭，孤魂拟向梦中来。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.50000.json#record-2fc43627-717f-49b2-ada4-3968d56dbd62","tags":[]},{"id":"poem-0c5ea7d7de351548c52eaf38","title":"南池","author":"杜甫","dynasty":"唐","verses":["峥嵘巴阆间，所向尽山谷。","安知有苍池，万顷浸坤轴。","呀然阆城南，枕带巴江腹。","芰荷入异县，稉稻共比屋。","皇天不无意，美利戒止足。","高田失西成，此物颇丰熟。","清源多众鱼，远岸富乔木。","独叹枫香林，春时好颜色。","南有汉王祠，终朝走巫祝。","歌舞散灵衣，荒哉旧风俗。","高堂亦明王，魂魄犹正直。","不应空陂上，缥缈亲酒食。","淫祀自古昔，非唯一川渎。","干戈浩茫茫，地僻伤极目。","平生江海兴，遭乱身局促。","驻马问渔舟，踌躇慰羁束。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.10000.json#record-c3b2e460-ab50-438c-b53e-57ef2aae3d8d","tags":[]},{"id":"poem-0c72570783d6432228955820","title":"寄所知","author":"李咸用","dynasty":"唐","verses":["曾将俎豆为儿戏，争奈干戈阻素心。","遁去不同秦客逐，病来还作越人吟。","名流古集典衣买，僻寺奇花贳酒寻。","从道趣时身计拙，如非所好肯开襟。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-0fac2f86-3808-453b-803b-3f5d3e2722f7","tags":[]},{"id":"poem-0c72ebc9fb3f14557b82eec2","title":"六桥春望","author":"王镃","dynasty":"宋","verses":["美人娇醉落花钿，船载笙歌出柳边。","春满六桥调马路，香风飘趁玉丝鞭。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.240000.json#record-02a112b3-5319-4a21-9ce8-7bd3fc527c8d","tags":[]},{"id":"poem-0c82355e59873152a90b7141","title":"力疾山下吴邨看杏花十九首 三","author":"司空图","dynasty":"唐","verses":["镜留雪鬓暖消无，春到棃花日又晡。","移取扶桑堦下种，年年看长碍金乌。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-083d4f1f-3033-44bd-a1df-c94e61e8bf87","tags":[]},{"id":"poem-0c836ee3cffcf1cb9fcae9a3","title":"女冠子·修蛾慢脸","author":"毛熙震","dynasty":"五代","verses":["修蛾慢脸，不语檀心一点，小山妆。","蝉鬓低含绿，罗衣淡拂黄。","闷来深院里，闲步落花傍。","纤手轻轻整，玉炉香。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-9-juan.json#record-45","tags":[]},{"id":"poem-0c8b00c199a5c0d51688a9d8","title":"夏日登观农楼和崔使君","author":"皎然","dynasty":"唐","verses":["片雨拂簷楹，烦襟四坐清。","霏微过麦陇，萧散傍莎城。","静爱和花落，幽闻入竹声。","朝观趣无限，高咏寄深情。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.45000.json#record-c53cc0fc-164a-4d47-bd2d-3183e60716dc","tags":[]},{"id":"poem-0c946a77490dad977faa961b","title":"遐方怨·花半坼","author":"温庭筠","dynasty":"唐","verses":["花半坼，雨初晴。","未卷珠帘，梦残，惆怅闻晓莺。","宿妆眉浅粉山横，约鬟鸾镜里，绣罗轻。"],"enabled":true,"collection":"花间集","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/五代诗词/huajianji/huajianji-2-juan.json#record-3","tags":[]},{"id":"poem-0ca08b740533165fcfe2b2b8","title":"大东","author":"佚名","dynasty":"先秦","verses":["有饛簋飧，有捄棘匕。周道如砥，其直如矢。君子所履，小人所视。眷言顾之，潸焉出涕。","小东大东，杼柚其空。纠纠葛屦，可以履霜。佻佻公子，行彼周行。既往既来，使我心疚。","有冽氿泉，无浸获薪。契契寤叹，哀我惮人。薪是获薪，尚可载也。哀我惮人，亦可息也。","东人之子，职劳不来。西人之子，粲粲衣服。舟人之子，熊罴是裘。私人之子，百僚是试。","或以其酒，不以其浆。鞙鞙佩璲，不以其长。维天有汉，监亦有光。跂彼织女，终日七襄。","虽则七襄，不成报章。睆彼牵牛，不以服箱。东有启明，西有长庚。有捄天毕，载施之行。","维南有箕，不可以簸扬。维北有斗，不可以挹酒浆。维南有箕，载翕其舌。维北有斗，西柄之揭。"],"enabled":true,"collection":"诗经","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/诗经/shijing.json#record-202","tags":[]},{"id":"poem-0cada0e4d39843f509b78019","title":"郊庙歌辞 武后大享昊天乐章 七","author":"不详","dynasty":"唐","verses":["樽浮九酝，礼备三周。","陈诚菲奠，契福神猷。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.0.json#record-48d76427-8d1c-425a-9425-e4d4a8751f74","tags":[]},{"id":"poem-0cb1a7962b66453607602029","title":"和友人喜相遇十首 三","author":"李咸用","dynasty":"唐","verses":["惠子休惊学五车，沛公方起斩长蛇。","六雄互欲吞诸国，四海终须作一家。","自古经纶成世务，暂时朱绿比朝霞。","人生心口宜相副，莫使尧阶草势斜。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.35000.json#record-2f35ca8f-b01e-41f8-b894-b19abf0e5179","tags":[]},{"id":"poem-0cc1b7ce9112ec1e997dd30e","title":"和登会稽山","author":"孙逖","dynasty":"唐","verses":["稽山碧湖上，势入东溟尽。","烟景昼清明，九峰争隐嶙。","望中厌朱绂，俗内探玄牝。","野老听鸣驺，山童拥行轸。","仙花寒未落，古蔓柔堪引。","竹磵入山多，松崖向天近。","云从海天去，日就江村陨。","能赋丘尝闻，和歌参不敏。","冥搜信冲漠，多士期标准。","愿奉濯缨心，长谣反招隐。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.5000.json#record-3d8f4974-52ac-48d7-9c0e-ba35e3341c87","tags":[]},{"id":"poem-0cd2d83634c50871397e0d82","title":"楚江怀古三首 二","author":"马戴","dynasty":"唐","verses":["惊鸟去无际，寒蛩鸣我傍。","芦洲生早雾，兰隰下微霜。","列宿分穷野，空流注大荒。","看山候明月，聊自整云装。"],"enabled":true,"collection":"全唐诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.tang.30000.json#record-14060d28-d860-41d2-9583-27873f1e0ac8","tags":[]},{"id":"poem-0ce5306e1bbf4c51c5f9d7a0","title":"合欢带·楼台高下玲珑","author":"杜安世","dynasty":"宋","verses":["楼台高下玲珑。","斗芳草、绿阴浓。","芍药孤栖香艳晚，见樱桃、万颗初红。","巢喧乳燕，珠帘镂曳，满户香风。","罩纱帏、象床屏枕，昼眠才似朦胧。","起来无语更兼慵。","念分明、事成空。","被你厌厌牵系我，怪纤腰、绣带宽松。","春来早是，分飞两处，长恨西东。","到如今、扇移明月，簟铺寒浪与谁同。"],"enabled":true,"collection":"宋词选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/宋词/ci.song.0.json#record-899","tags":[]},{"id":"poem-0cf01134ad06d164aac202b7","title":"送僧造普同塔","author":"释行机","dynasty":"宋","verses":["珊珊玉骨本玲珑，挂角羚羊不见踪。","特地作亭图甚么，为怜松竹引清风。"],"enabled":true,"collection":"宋诗选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/全唐诗/poet.song.120000.json#record-b2d4a017-6ad4-414e-b3ea-4b3715607e1c","tags":[]},{"id":"poem-0cf0a9d3efa505ed5c84a0ad","title":"前腔","author":"徐田臣《杀狗记》","dynasty":"元","verses":["(小生上)背尸骸出城去离，幸喜得巡军皆睡，且喜街上，没个人迹。","埋他在土沙中深草径，荒郊外回来贺喜。"],"enabled":true,"collection":"元曲选","source":"https://github.com/chinese-poetry/chinese-poetry/blob/b8594f81a89752241442f2ce267d6f66f96704ee/元曲/yuanqu.json#record-1930","tags":[]}];
